window.PE_COURSE={"qualification": "AQA A-level Physical Education 7582", "reviewed": "2026-10-23", "units": [{"id": "anatomy", "title": "Applied anatomy and physiology", "ref": "3.1.1", "paper": 1}, {"id": "skill", "title": "Skill acquisition", "ref": "3.1.2", "paper": 1}, {"id": "society", "title": "Sport and society", "ref": "3.1.3", "paper": 1}, {"id": "exercise", "title": "Exercise physiology", "ref": "3.2.1", "paper": 2}, {"id": "biomechanics", "title": "Biomechanical movement", "ref": "3.2.2", "paper": 2}, {"id": "psychology", "title": "Sport psychology", "ref": "3.2.3", "paper": 2}, {"id": "contemporary", "title": "Sport, society and technology", "ref": "3.2.4", "paper": 2}, {"id": "nea", "title": "Practical performance and analysis", "ref": "4.5", "paper": null}], "lessons": [{"id": "cardiac-output", "unit": "anatomy", "title": "Heart structure and cardiac output", "ref": "3.1.1.1–2", "summary": "Cardiac output is heart rate multiplied by stroke volume.", "notes": ["The right heart sends deoxygenated blood to the lungs; the left heart pumps oxygenated blood to the body. Valves prevent backflow. Heart rate is beats per minute and stroke volume is blood ejected per beat. During exercise both can rise, increasing oxygen delivery. Endurance training can increase stroke volume, so a trained performer may have a lower heart rate at the same submaximal workload. Maximum heart rate is not simply increased by training. Regular activity can support cardiovascular health, while high blood pressure and atherosclerotic plaque can increase heart disease and stroke risk. Distinguish health risk from performance fitness; cholesterol contributes to normal physiology but adverse blood-lipid patterns can contribute to plaque development.", "150 × 120 = 18 000 mL min⁻¹ = 18 L min⁻¹. Keep the per-minute unit and convert millilitres to litres. An increased flow supports oxygen delivery, but delivery also depends on blood oxygen content and distribution."], "worked": "A fictional rower has a heart rate of 150 beats min⁻¹ and stroke volume of 120 mL beat⁻¹. Calculate cardiac output.", "question": "A cyclist has a heart rate of 160 beats min⁻¹ and stroke volume of 125 mL beat⁻¹. Calculate cardiac output in L min⁻¹ and explain its value during exercise.", "scheme": ["Use Q = HR × SV.", "160 × 125 = 20 000 mL min⁻¹.", "Convert to 20 L min⁻¹.", "Greater flow can deliver more oxygen per minute to working muscles, supporting aerobic ATP resynthesis."], "checks": [{"q": "Which statement is accurate?", "opts": ["Cardiac output is heart rate multiplied by stroke volume.", "Cardiac output is stroke volume divided by heart rate.", "Training necessarily raises maximum heart rate."], "a": 0, "why": "Cardiac output is heart rate multiplied by stroke volume. 150 × 120 = 18 000 mL min⁻¹ = 18 L min⁻¹. Keep the per-minute unit and convert millilitres to litres. An increased flow supports oxygen delivery, but delivery also depends on blood oxygen content and distribution."}], "animation": "cardiac"}, {"id": "cardiac-regulation", "unit": "anatomy", "title": "Cardiac conduction and regulation", "ref": "3.1.1.2", "summary": "The sinoatrial node initiates the normal heartbeat; autonomic input changes its rate.", "notes": ["The sinoatrial node initiates excitation, which spreads across the atria. Delay at the atrioventricular node allows ventricular filling before conduction through the bundle of His and Purkinje fibres produces coordinated ventricular contraction. Sympathetic activity and adrenaline increase rate and contractility; parasympathetic input slows the heart. An anticipatory rise can occur before movement begins.", "Central anticipation and sympathetic stimulation help explain the rise before muscle demand has increased substantially. During activity, proprioceptors signal movement, chemoreceptors respond to chemical changes and baroreceptors respond to pressure. Avoid describing any one receptor as the sole controller."], "worked": "A runner’s heart rate rises on the start line before the race.", "question": "Explain how a games player can increase heart rate both before a match and after intense play begins.", "scheme": ["Before play, anticipation can increase sympathetic stimulation.", "This increases sinoatrial node firing and heart rate.", "During play, proprioceptor and chemoreceptor information contributes to cardiovascular regulation.", "The increased rate contributes to greater cardiac output and muscle oxygen delivery."], "checks": [{"q": "Which statement is accurate?", "opts": ["The atrioventricular node normally starts every heartbeat before the sinoatrial node.", "The heart needs a new conscious decision for every beat.", "The sinoatrial node initiates the normal heartbeat; autonomic input changes its rate."], "a": 2, "why": "The sinoatrial node initiates the normal heartbeat; autonomic input changes its rate. Central anticipation and sympathetic stimulation help explain the rise before muscle demand has increased substantially. During activity, proprioceptors signal movement, chemoreceptors respond to chemical changes and baroreceptors respond to pressure. Avoid describing any one receptor as the sole controller."}], "animation": null}, {"id": "oxygen-transport", "unit": "anatomy", "title": "Oxygen transport and the Bohr shift", "ref": "3.1.1.2", "summary": "A rightward shift of the oxyhaemoglobin curve promotes oxygen unloading at a given partial pressure.", "notes": ["Most oxygen is carried bound to haemoglobin. The dissociation curve is sigmoid because binding is cooperative. High oxygen partial pressure in the lungs favours loading; lower partial pressure in active tissue favours unloading. Increased carbon dioxide and acidity reduce affinity, contributing to a rightward Bohr shift. Myoglobin in muscle has a high affinity for oxygen and helps maintain oxygen availability within muscle.", "Lower affinity means more oxygen can be released to the active tissue. The curve is not a direct graph of how much oxygen the athlete consumes. Describe the axes, the direction of the shift and its effect at a specified partial pressure."], "worked": "At the same tissue oxygen partial pressure, haemoglobin is less saturated in a hot, active muscle than under resting conditions.", "question": "Explain how increased carbon dioxide in a sprinter’s active muscles can assist oxygen unloading.", "scheme": ["Carbon dioxide increases as muscle metabolism rises.", "Associated acidity reduces haemoglobin’s oxygen affinity.", "The dissociation curve shifts right, so saturation is lower at a given oxygen partial pressure.", "More oxygen unloads to muscle, supporting its aerobic contribution."], "checks": [{"q": "Which statement is accurate?", "opts": ["Myoglobin is the main protein transporting oxygen around the blood.", "A rightward shift of the oxyhaemoglobin curve promotes oxygen unloading at a given partial pressure.", "A Bohr shift makes haemoglobin bind oxygen more tightly at active tissues."], "a": 1, "why": "A rightward shift of the oxyhaemoglobin curve promotes oxygen unloading at a given partial pressure. Lower affinity means more oxygen can be released to the active tissue. The curve is not a direct graph of how much oxygen the athlete consumes. Describe the axes, the direction of the shift and its effect at a specified partial pressure."}], "animation": null}, {"id": "venous-return", "unit": "anatomy", "title": "Venous return, blood pressure and drift", "ref": "3.1.1.2", "summary": "Greater venous return can increase ventricular filling and stroke volume through the Frank–Starling mechanism.", "notes": ["Venous return is assisted by skeletal-muscle and respiratory pumps, venous valves and sympathetic venoconstriction. Greater end-diastolic filling stretches cardiac muscle within its physiological range, supporting a stronger contraction. Systolic pressure occurs during ventricular contraction; diastolic pressure during relaxation. During prolonged exercise, heat and fluid loss can reduce plasma volume and stroke volume, with heart rate rising to help sustain cardiac output: cardiovascular drift.", "The pattern is compatible with cardiovascular drift; it does not by itself diagnose a condition. Redistribution of blood and reduced circulating volume affect filling. Cardiac output can be partly maintained by heart rate, but compensation is not unlimited. Interpret changes together rather than treating heart rate alone as fitness."], "worked": "Two runners maintain the same pace, but one shows rising heart rate and falling stroke volume in prolonged heat.", "question": "Explain two mechanisms assisting a cyclist’s venous return and link return to stroke volume.", "scheme": ["Contracting skeletal muscles compress veins and move blood towards the heart.", "Valves limit backflow; respiratory pressure changes also assist return.", "Greater return increases ventricular filling/end-diastolic volume.", "Within normal limits the Frank–Starling response increases contraction force and stroke volume."], "checks": [{"q": "Which statement is accurate?", "opts": ["Greater venous return can increase ventricular filling and stroke volume through the Frank–Starling mechanism.", "Veins lack valves and return blood only by gravity.", "Cardiovascular drift necessarily means stroke volume rises throughout prolonged heat."], "a": 0, "why": "Greater venous return can increase ventricular filling and stroke volume through the Frank–Starling mechanism. The pattern is compatible with cardiovascular drift; it does not by itself diagnose a condition. Redistribution of blood and reduced circulating volume affect filling. Cardiac output can be partly maintained by heart rate, but compensation is not unlimited. Interpret changes together rather than treating heart rate alone as fitness."}], "animation": null}, {"id": "vascular-shunting", "unit": "anatomy", "title": "Vascular shunting and oxygen extraction", "ref": "3.1.1.2", "summary": "Blood distribution and arterio-venous oxygen difference both contribute to exercising muscle oxygen supply.", "notes": ["Working muscle arterioles dilate while flow to some less immediately active tissues can decrease through vasoconstriction. Control is both local and neural; blood is redistributed rather than created. The arterio-venous oxygen difference measures oxygen extracted from each volume of blood. The Fick relationship links oxygen consumption to cardiac output multiplied by that difference, using consistent units.", "Increased flow and increased extraction are complementary. Venous blood still normally contains oxygen; muscles do not extract every molecule. Endurance adaptations include capillary and mitochondrial changes, which support extraction and aerobic metabolism."], "worked": "During cycling, blood reaches active leg muscles faster and venous blood returning from those muscles contains less oxygen.", "question": "Explain why a runner can increase oxygen consumption even when the oxygen content of arterial blood changes little.", "scheme": ["Exercise increases cardiac output.", "Vasodilation increases the proportion of flow reaching active muscle.", "Muscle extracts more oxygen, increasing arterio-venous oxygen difference.", "Greater flow multiplied by greater extraction raises oxygen consumption."], "checks": [{"q": "Which statement is accurate?", "opts": ["Vascular shunting creates additional blood cells immediately.", "Arterio-venous oxygen difference is the difference between two heart rates.", "Blood distribution and arterio-venous oxygen difference both contribute to exercising muscle oxygen supply."], "a": 2, "why": "Blood distribution and arterio-venous oxygen difference both contribute to exercising muscle oxygen supply. Increased flow and increased extraction are complementary. Venous blood still normally contains oxygen; muscles do not extract every molecule. Endurance adaptations include capillary and mitochondrial changes, which support extraction and aerobic metabolism."}], "animation": null}, {"id": "ventilation", "unit": "anatomy", "title": "Lung volumes and ventilation", "ref": "3.1.1.3", "summary": "Minute ventilation equals tidal volume multiplied by breathing frequency.", "notes": ["Tidal volume is air moved in a normal breath; inspiratory and expiratory reserve volumes are additional volumes above and below that breath. Residual volume remains after maximal expiration and prevents complete emptying. Exercise increases depth and frequency of breathing. Minute ventilation is total air moved per minute, not the amount of oxygen absorbed into blood.", "Multiply volume per breath by breaths per minute and retain L min⁻¹. Total ventilation includes air in conducting airways, so it differs from alveolar ventilation. Residual volume cannot be expelled by simply breathing out harder."], "worked": "A swimmer breathes 30 times min⁻¹ with tidal volume 2.0 L: minute ventilation is 60 L min⁻¹.", "question": "A runner’s tidal volume is 2.4 L and breathing frequency is 35 min⁻¹. Calculate minute ventilation and distinguish it from oxygen uptake.", "scheme": ["Use minute ventilation = tidal volume × frequency.", "2.4 × 35 = 84.", "State 84 L min⁻¹.", "This is air moved, whereas oxygen uptake measures oxygen transferred and used per minute."], "checks": [{"q": "Which statement is accurate?", "opts": ["Residual volume is the air normally exhaled in a quiet breath.", "Minute ventilation equals tidal volume multiplied by breathing frequency.", "Minute ventilation is tidal volume divided by breathing frequency."], "a": 1, "why": "Minute ventilation equals tidal volume multiplied by breathing frequency. Multiply volume per breath by breaths per minute and retain L min⁻¹. Total ventilation includes air in conducting airways, so it differs from alveolar ventilation. Residual volume cannot be expelled by simply breathing out harder."}], "animation": null}, {"id": "gas-exchange", "unit": "anatomy", "title": "Gas exchange, ventilation control and smoking", "ref": "3.1.1.3", "summary": "Gases diffuse down their own partial-pressure gradients at the lungs and tissues.", "notes": ["A large surface area, thin barrier and maintained blood flow support alveolar exchange. Oxygen diffuses into blood because its partial pressure is higher in alveolar air; carbon dioxide moves the opposite way. At muscle the gradients reverse. Neural input and chemical feedback increase ventilation during exercise, including responses to carbon dioxide/acidity. Proprioceptor signals can increase breathing before chemical changes become large.", "The larger gradient supports diffusion from blood to muscle. Smoking can impair cilia and damage respiratory surfaces; carbon monoxide binds haemoglobin and reduces oxygen-carrying capacity. Distinguish impaired gas exchange from reduced carriage: both can restrict delivery by different mechanisms."], "worked": "A muscle uses oxygen quickly, lowering local oxygen partial pressure.", "question": "Explain how alveolar structure and blood flow maintain rapid oxygen diffusion during exercise.", "scheme": ["A large alveolar surface provides a large exchange area.", "Thin alveolar/capillary walls shorten diffusion distance.", "Ventilation replenishes alveolar oxygen and blood flow removes oxygenated blood.", "These processes maintain a partial-pressure gradient into blood."], "checks": [{"q": "Which statement is accurate?", "opts": ["Gases diffuse down their own partial-pressure gradients at the lungs and tissues.", "Oxygen and carbon dioxide always diffuse in the same direction.", "Gas exchange requires the alveoli to actively pump oxygen molecules."], "a": 0, "why": "Gases diffuse down their own partial-pressure gradients at the lungs and tissues. The larger gradient supports diffusion from blood to muscle. Smoking can impair cilia and damage respiratory surfaces; carbon monoxide binds haemoglobin and reduces oxygen-carrying capacity. Distinguish impaired gas exchange from reduced carriage: both can restrict delivery by different mechanisms."}], "animation": null}, {"id": "muscle-fibres", "unit": "anatomy", "title": "Muscle fibre types and sporting demands", "ref": "3.1.1.4", "summary": "Type I, IIa and IIx fibres differ in force, fatigue resistance and metabolic characteristics.", "notes": ["Type I fibres have high oxidative capacity, many mitochondria and capillaries and strong fatigue resistance, but relatively low force and shortening speed. Type IIx fibres produce high force rapidly and fatigue quickly, with greater glycolytic capacity. Type IIa fibres combine fast contraction with greater oxidative capacity than IIx. Events recruit a mixture, and training modifies characteristics; fibre type alone does not determine sporting success.", "Type I characteristics suit sustained aerobic demand; fast fibres support high force and power. Do not claim that a marathon uses no fast fibres or a jump uses no aerobic metabolism. Recruitment changes with force requirements and fatigue."], "worked": "A distance runner sustains repeated contractions for a long race, while a jumper requires rapid high-force take-off.", "question": "Compare fibre characteristics that help a track cyclist in a short sprint and in a long endurance event.", "scheme": ["Sprinting benefits from fast shortening and high force from type II fibres.", "Greater glycolytic capacity supports rapid ATP resynthesis.", "Endurance benefits from oxidative type I characteristics and fatigue resistance.", "Mitochondria/capillary supply support sustained aerobic resynthesis; both events still recruit mixed fibres."], "checks": [{"q": "Which statement is accurate?", "opts": ["Type IIx fibres are the most fatigue-resistant fibres.", "Every endurance movement uses only type I fibres.", "Type I, IIa and IIx fibres differ in force, fatigue resistance and metabolic characteristics."], "a": 2, "why": "Type I, IIa and IIx fibres differ in force, fatigue resistance and metabolic characteristics. Type I characteristics suit sustained aerobic demand; fast fibres support high force and power. Do not claim that a marathon uses no fast fibres or a jump uses no aerobic metabolism. Recruitment changes with force requirements and fatigue."}], "animation": null}, {"id": "motor-units", "unit": "anatomy", "title": "Motor units, recruitment and summation", "ref": "3.1.1.4", "summary": "Force can increase by recruiting more motor units and by increasing firing frequency.", "notes": ["A motor unit consists of a motor neurone and the muscle fibres it innervates. The all-or-none law applies to an individual activated motor unit, not the entire muscle’s possible force. Spatial summation recruits additional units. Wave summation increases stimulus frequency before full relaxation, increasing tension; sufficiently high frequency can produce tetanic contraction. Recruitment is generally graded as demand rises.", "Extra force does not mean each fibre produces half an action potential. More units and altered firing frequency grade whole-muscle force. Muscle spindles detect stretch; Golgi tendon organs monitor tension. These proprioceptors provide feedback relevant to movement and flexibility training. In the syllabus model of PNF, a controlled isometric contraction and subsequent relaxation are linked with reduced resistance to a further stretch, including inhibitory effects associated with tension feedback. A muscle spindle responds to length/change in length; the Golgi tendon organ responds to tension. PNF needs suitable supervision rather than forcing a painful stretch."], "worked": "A lifter grips an empty bar gently, then grips a heavier bar more strongly.", "question": "Explain how a muscle increases force while the all-or-none principle still applies.", "scheme": ["An activated motor unit responds fully to a sufficient stimulus.", "Recruiting more units increases the number of active fibres.", "Higher firing frequency permits wave summation before complete relaxation.", "Total muscle tension therefore varies although individual action potentials are not graded in size."], "checks": [{"q": "Which statement is accurate?", "opts": ["Spatial summation means increasing the size of one action potential.", "Force can increase by recruiting more motor units and by increasing firing frequency.", "All-or-none means the whole muscle can produce only one force."], "a": 1, "why": "Force can increase by recruiting more motor units and by increasing firing frequency. Extra force does not mean each fibre produces half an action potential. More units and altered firing frequency grade whole-muscle force. Muscle spindles detect stretch; Golgi tendon organs monitor tension. These proprioceptors provide feedback relevant to movement and flexibility training. In the syllabus model of PNF, a controlled isometric contraction and subsequent relaxation are linked with reduced resistance to a further stretch, including inhibitory effects associated with tension feedback. A muscle spindle responds to length/change in length; the Golgi tendon organ responds to tension. PNF needs suitable supervision rather than forcing a painful stretch."}], "animation": null}, {"id": "movement-analysis", "unit": "anatomy", "title": "Joints, planes, axes and movement analysis", "ref": "3.1.1.5", "summary": "A movement’s plane is perpendicular to its axis of rotation.", "notes": ["Sagittal-plane flexion and extension occur about a transverse axis. Frontal-plane abduction and adduction occur about a sagittal axis. Transverse-plane horizontal abduction/adduction and rotation occur about a longitudinal axis. The shoulder and hip are ball-and-socket joints; elbow and knee are usually treated as hinge joints in sporting movement analysis. Identify the joint, articulating bones, action and main working muscles at a specified phase.", "The movement is in the sagittal plane about a transverse axis. A muscle can change its role between phases, so a joint name alone does not establish the action. At the ankle distinguish plantar flexion from dorsiflexion rather than calling both movements extension. Shoulder and hip flexion/extension use the sagittal plane; their abduction/adduction uses the frontal plane, and horizontal abduction/adduction the transverse plane. The hip joins pelvis and femur; the knee femur and tibia; the ankle tibia/fibula and talus. Gluteals/hamstrings can extend the hip, quadriceps extend the knee, hamstrings flex it, gastrocnemius/soleus plantar-flex and tibialis anterior dorsi-flexes. Select the relevant phase before naming the main agonist."], "worked": "In the upward phase of a biceps curl, the elbow flexes as biceps shortens, with the humerus articulating with radius/ulna.", "question": "Analyse the knee during the upward phase of a squat: action, plane, axis and main agonist.", "scheme": ["The knee extends during the upward phase.", "Movement is in the sagittal plane.", "Rotation is about a transverse axis.", "Quadriceps acts as the main agonist, shortening concentrically in the controlled upward phase."], "checks": [{"q": "Which statement is accurate?", "opts": ["A movement’s plane is perpendicular to its axis of rotation.", "Sagittal-plane movement takes place about a longitudinal axis.", "Abduction moves a limb towards the body’s midline."], "a": 0, "why": "A movement’s plane is perpendicular to its axis of rotation. The movement is in the sagittal plane about a transverse axis. A muscle can change its role between phases, so a joint name alone does not establish the action. At the ankle distinguish plantar flexion from dorsiflexion rather than calling both movements extension. Shoulder and hip flexion/extension use the sagittal plane; their abduction/adduction uses the frontal plane, and horizontal abduction/adduction the transverse plane. The hip joins pelvis and femur; the knee femur and tibia; the ankle tibia/fibula and talus. Gluteals/hamstrings can extend the hip, quadriceps extend the knee, hamstrings flex it, gastrocnemius/soleus plantar-flex and tibialis anterior dorsi-flexes. Select the relevant phase before naming the main agonist."}], "animation": "muscle"}, {"id": "muscle-contractions", "unit": "anatomy", "title": "Agonists, antagonists and contractions", "ref": "3.1.1.5", "summary": "A muscle can produce tension while shortening, lengthening or maintaining its length.", "notes": ["Concentric contraction shortens an active muscle; eccentric contraction lengthens it under tension; isometric contraction maintains length. An agonist supplies the main force for an action, while antagonists can oppose or control it. In a controlled lowering phase the same muscle that lifted a load may contract eccentrically. It is not necessarily relaxed just because the load moves down.", "Biceps remains active while lengthening, controlling the downward movement eccentrically. The elbow extends, but this does not automatically mean triceps supplies the principal controlling force. Analyse the external load and movement phase together."], "worked": "A performer lowers a dumbbell slowly from elbow flexion towards extension.", "question": "Compare quadriceps action when rising from a squat and when lowering slowly into the squat.", "scheme": ["Rising involves knee extension.", "Quadriceps shortens under tension: concentric.", "Lowering involves controlled knee flexion while quadriceps lengthens under tension.", "This is eccentric action; tension does not imply that the muscle must shorten."], "checks": [{"q": "Which statement is accurate?", "opts": ["An active muscle can create tension only while shortening.", "Eccentric contraction means the muscle is relaxed.", "A muscle can produce tension while shortening, lengthening or maintaining its length."], "a": 2, "why": "A muscle can produce tension while shortening, lengthening or maintaining its length. Biceps remains active while lengthening, controlling the downward movement eccentrically. The elbow extends, but this does not automatically mean triceps supplies the principal controlling force. Analyse the external load and movement phase together."}], "animation": "muscle"}, {"id": "atp-pc", "unit": "anatomy", "title": "ATP and the ATP–PC system", "ref": "3.1.1.6", "summary": "Phosphocreatine rapidly resynthesises ATP but its available store is limited.", "notes": ["ATP hydrolysis supplies immediate energy for contraction. Stored ATP is small and must be continually resynthesised. In the ATP–PC system, phosphocreatine supplies a phosphate to ADP through creatine kinase. It is anaerobic, has a very high rate of supply and a low capacity. It contributes strongly to brief explosive efforts, but no event switches neatly between completely isolated systems.", "Rapid supply supports explosive force before slower systems can match the rate of demand. Recovery between attempts permits aerobic support of phosphocreatine restoration. Avoid a fixed second at which the system suddenly stops; availability and intensity vary."], "worked": "A thrower produces a maximal effort lasting only a few seconds.", "question": "Explain why ATP–PC contribution is valuable at a long jumper’s take-off but cannot supply an entire 1500 m race.", "scheme": ["ATP is needed immediately for contraction.", "Phosphocreatine rapidly donates phosphate to resynthesise ATP anaerobically.", "High supply rate supports the explosive take-off.", "Limited phosphocreatine capacity prevents sustained sole supply during a long event."], "checks": [{"q": "Which statement is accurate?", "opts": ["ATP–PC reactions require oxygen directly.", "Phosphocreatine rapidly resynthesises ATP but its available store is limited.", "Phosphocreatine provides an unlimited ATP store."], "a": 1, "why": "Phosphocreatine rapidly resynthesises ATP but its available store is limited. Rapid supply supports explosive force before slower systems can match the rate of demand. Recovery between attempts permits aerobic support of phosphocreatine restoration. Avoid a fixed second at which the system suddenly stops; availability and intensity vary."}], "animation": "energy"}, {"id": "glycolytic-aerobic", "unit": "anatomy", "title": "Glycolytic and aerobic energy pathways", "ref": "3.1.1.6", "summary": "Energy systems overlap; relative contribution depends on intensity, duration and oxygen availability.", "notes": ["Anaerobic glycolysis in the cytoplasm rapidly breaks down carbohydrate, allowing ATP production when glycolytic demand exceeds mitochondrial oxidation. Lactate can be transported and used as fuel; it is not simply a poisonous waste product. Aerobic pathways include glycolysis, the Krebs/citric-acid cycle and the electron transport chain; fat also enters aerobic metabolism through beta oxidation. Aerobic supply is slower but has much larger capacity.", "All systems contribute, but high intensity increases reliance on rapid anaerobic supply. Aerobic metabolism contributes during the race and recovery. Lactate threshold concerns an exercise intensity beyond which blood lactate rises progressively; the conventional OBLA reference is 4 mmol L⁻¹, not a universal personalised threshold."], "worked": "An athlete runs a hard 400 m and then walks during recovery.", "question": "Explain why a marathon runner relies heavily on aerobic metabolism but still increases anaerobic contribution during a finishing sprint.", "scheme": ["Aerobic pathways can sustain a large ATP yield over a long duration.", "Carbohydrate and fat support prolonged aerobic resynthesis.", "A finishing sprint raises the required rate of ATP supply.", "Rapid anaerobic pathways increase their relative contribution while aerobic supply continues."], "checks": [{"q": "Which statement is accurate?", "opts": ["Energy systems overlap; relative contribution depends on intensity, duration and oxygen availability.", "The aerobic system switches off whenever a sprint begins.", "Lactate can never be reused as a fuel."], "a": 0, "why": "Energy systems overlap; relative contribution depends on intensity, duration and oxygen availability. All systems contribute, but high intensity increases reliance on rapid anaerobic supply. Aerobic metabolism contributes during the race and recovery. Lactate threshold concerns an exercise intensity beyond which blood lactate rises progressively; the conventional OBLA reference is 4 mmol L⁻¹, not a universal personalised threshold."}], "animation": "energy"}, {"id": "oxygen-deficit", "unit": "anatomy", "title": "Oxygen deficit, EPOC and energy measurement", "ref": "3.1.1.6", "summary": "Oxygen uptake takes time to match demand and remains elevated during recovery.", "notes": ["Oxygen deficit is the initial shortfall between oxygen demand and actual uptake; anaerobic sources help meet the ATP demand. Excess post-exercise oxygen consumption supports processes including phosphocreatine restoration and reoxygenation, with a slower component influenced by elevated temperature, hormones and other recovery processes. VO₂ max reflects maximal oxygen uptake; cardiac output, oxygen carriage and extraction all contribute.", "Elevated oxygen uptake is not solely repayment of a single lactate debt. Indirect calorimetry estimates energy expenditure from respiratory gases. RER is carbon dioxide output divided by oxygen uptake; interpretation as fuel use is most appropriate in steady conditions. Lactate sampling and VO₂ testing measure different aspects of exercise response."], "worked": "A runner stops but continues breathing heavily while recovering.", "question": "A steady-state test gives VCO₂ = 2.4 L min⁻¹ and VO₂ = 3.0 L min⁻¹. Calculate RER and explain one limitation when applying it during an all-out sprint.", "scheme": ["RER = VCO₂ / VO₂.", "2.4 / 3.0 = 0.80, with no unit.", "During intense non-steady exercise extra CO₂ can arise from buffering.", "RER then does not provide a simple direct measure of substrate proportions."], "checks": [{"q": "Which statement is accurate?", "opts": ["EPOC is caused exclusively by lactate removal.", "RER equals oxygen uptake divided by carbon dioxide output.", "Oxygen uptake takes time to match demand and remains elevated during recovery."], "a": 2, "why": "Oxygen uptake takes time to match demand and remains elevated during recovery. Elevated oxygen uptake is not solely repayment of a single lactate debt. Indirect calorimetry estimates energy expenditure from respiratory gases. RER is carbon dioxide output divided by oxygen uptake; interpretation as fuel use is most appropriate in steady conditions. Lactate sampling and VO₂ testing measure different aspects of exercise response."}], "animation": "energy"}, {"id": "skill-continua", "unit": "skill", "title": "Classifying skills on continua", "ref": "3.1.2.1", "summary": "Skill classification depends on the specific action and environment rather than the sport’s name alone.", "notes": ["Skilful movement is learned, purposeful, coordinated and efficient. Open skills respond to a changing environment; closed skills occur in more predictable settings. Discrete skills have a clear beginning/end, serial skills link discrete actions and continuous skills repeat cyclically. Gross/fine concerns movement control, self/externally paced concerns timing, and simple/complex concerns processing demands. State what the high/low organisation continuum is measuring when applying it.", "The free throw is relatively closed and self-paced; the contested pass is more open and externally paced. Both have large muscle involvement but also fine control. Continua permit intermediate positions: do not force every action into a universal binary label."], "worked": "Compare a free throw with a pass made while defenders move.", "question": "Place a tennis serve on two skill continua and justify each placement.", "scheme": ["Identify the serve as relatively closed compared with a rally response.", "The server initiates the action with less immediate environmental change.", "It is relatively self-paced.", "The server largely controls when the movement begins, within the game’s rules."], "checks": [{"q": "Which statement is accurate?", "opts": ["An open skill occurs only outdoors.", "Skill classification depends on the specific action and environment rather than the sport’s name alone.", "Every skill within a sport occupies exactly the same continuum position."], "a": 1, "why": "Skill classification depends on the specific action and environment rather than the sport’s name alone. The free throw is relatively closed and self-paced; the contested pass is more open and externally paced. Both have large muscle involvement but also fine control. Continua permit intermediate positions: do not force every action into a universal binary label."}], "animation": null}, {"id": "transfer", "unit": "skill", "title": "Transfer of learning", "ref": "3.1.2.1", "summary": "Transfer can help, hinder or have little effect on learning another skill.", "notes": ["Positive transfer occurs when prior learning aids a new task; negative transfer interferes. Zero transfer has little detectable effect, while bilateral transfer involves learning carrying across limbs. Similarity in perceptual cues, movement or decision demands can facilitate learning, but superficially similar actions may require different timing. Identify the old and new tasks and explain the actual connection.", "An established response can interfere with the new technique, illustrating negative transfer. A coach can highlight the differences and provide focused practice. Improvement after practice alone does not prove positive transfer without comparing appropriate starting conditions."], "worked": "A player accustomed to one striking action initially uses inappropriate timing with a different implement.", "question": "Explain how practising a football pass with the dominant foot might assist the non-dominant foot, and state a limitation.", "scheme": ["This can illustrate bilateral transfer.", "Understanding of the action and coordination pattern may carry across limbs.", "It can support learning with the non-dominant foot.", "The limbs still require specific practice; equivalent performance is not guaranteed."], "checks": [{"q": "Which statement is accurate?", "opts": ["Transfer can help, hinder or have little effect on learning another skill.", "Transfer is always positive.", "Bilateral transfer means moving from one sport to another."], "a": 0, "why": "Transfer can help, hinder or have little effect on learning another skill. An established response can interfere with the new technique, illustrating negative transfer. A coach can highlight the differences and provide focused practice. Improvement after practice alone does not prove positive transfer without comparing appropriate starting conditions."}], "animation": null}, {"id": "practice-design", "unit": "skill", "title": "Practice structure and presentation", "ref": "3.1.2.2", "summary": "Effective practice structure depends on the learner, task and fatigue demands.", "notes": ["Whole practice preserves a complete action; part practice isolates components. Progressive part gradually links learned sections; whole–part–whole identifies a weakness then reintegrates it. Highly organised skills can lose timing when split. Massed practice gives little rest; distributed practice includes recovery. Variable practice changes relevant conditions and mental practice rehearses the task without overt movement.", "Distributed practice creates recovery and feedback opportunities, helping maintain quality. A complex sequence may benefit from progressive part, but a tightly integrated explosive action may require preservation of its whole rhythm. Explain the suitability, not merely the practice label."], "worked": "A novice becomes tired and repeats an unsafe landing error late in a long practice block.", "question": "Justify variable and distributed practice for a novice badminton player learning to respond to different shots.", "scheme": ["Vary shot direction/depth so practice matches an open skill.", "This develops selection and adaptation rather than one fixed response.", "Include rest and feedback intervals.", "Distributed practice limits fatigue and supports attention and safe technique."], "checks": [{"q": "Which statement is accurate?", "opts": ["Massed practice is always the best choice for every novice.", "Variable practice means practising without any goal.", "Effective practice structure depends on the learner, task and fatigue demands."], "a": 2, "why": "Effective practice structure depends on the learner, task and fatigue demands. Distributed practice creates recovery and feedback opportunities, helping maintain quality. A complex sequence may benefit from progressive part, but a tightly integrated explosive action may require preservation of its whole rhythm. Explain the suitability, not merely the practice label."}], "animation": null}, {"id": "learning-stages", "unit": "skill", "title": "Learning stages and plateaux", "ref": "3.1.2.3", "summary": "Guidance and feedback should adapt as performance progresses from cognitive to autonomous control.", "notes": ["Cognitive learners understand the task and make frequent errors, needing clear demonstrations and manageable cues. Associative learners refine technique and improve consistency, benefiting from specific feedback. Autonomous performers execute established components with less conscious attention, freeing attention for tactics. A learning plateau may reflect fatigue, motivation, task difficulty or a technique limit; it does not prove that learning has permanently ended.", "Reduced conscious control of an established action can support decision making. A coach should not overload an expert with continuous elementary instructions. Diagnose a plateau with evidence, then vary challenge, rest or feedback as appropriate."], "worked": "A beginner consciously checks foot position, while an experienced player attends to opponents.", "question": "Explain how feedback to a novice learning a serve should differ from feedback to a highly experienced server.", "scheme": ["A novice needs clear basic cues and demonstration.", "Frequent, specific external feedback can identify major errors.", "An experienced player can use refined knowledge of performance and intrinsic feedback.", "Feedback should target a specific change without disrupting established automatic control."], "checks": [{"q": "Which statement is accurate?", "opts": ["Autonomous performers never need feedback.", "Guidance and feedback should adapt as performance progresses from cognitive to autonomous control.", "A plateau proves no further learning is possible."], "a": 1, "why": "Guidance and feedback should adapt as performance progresses from cognitive to autonomous control. Reduced conscious control of an established action can support decision making. A coach should not overload an expert with continuous elementary instructions. Diagnose a plateau with evidence, then vary challenge, rest or feedback as appropriate."}], "animation": null}, {"id": "learning-theories", "unit": "skill", "title": "Learning theories in coaching", "ref": "3.1.2.3", "summary": "Learning theories describe different mechanisms that can inform coaching decisions.", "notes": ["Operant conditioning links behaviour to consequences, such as reinforcement of a successful technique. Observational learning involves attention, retention, motor reproduction and motivation; a suitable model matters. Gestalt insight concerns understanding the task as a whole and suddenly reorganising a solution. Vygotsky’s social-development perspective emphasises supported learning within the zone of proximal development, where a learner can succeed with assistance before working independently.", "Demonstration supports observational learning; temporary support can be understood as scaffolding. Rewarding a desired action illustrates reinforcement, not proof that every skill can be taught by reward alone. Link a theory’s mechanism to the actual coaching choice."], "worked": "A coach demonstrates, highlights two cues, supports a first attempt and gradually removes assistance.", "question": "Apply Bandura’s observational-learning processes to teaching a novice a basketball lay-up.", "scheme": ["Direct attention to a suitable model and key cues.", "Support retention with a brief cue sequence or rehearsal.", "Provide opportunities for motor reproduction at an achievable level.", "Support motivation through attainable goals and useful feedback."], "checks": [{"q": "Which statement is accurate?", "opts": ["Learning theories describe different mechanisms that can inform coaching decisions.", "Observational learning requires watching without attention.", "Negative reinforcement means adding a punishment."], "a": 0, "why": "Learning theories describe different mechanisms that can inform coaching decisions. Demonstration supports observational learning; temporary support can be understood as scaffolding. Rewarding a desired action illustrates reinforcement, not proof that every skill can be taught by reward alone. Link a theory’s mechanism to the actual coaching choice."}], "animation": null}, {"id": "guidance-feedback", "unit": "skill", "title": "Guidance and feedback", "ref": "3.1.2.4", "summary": "Knowledge of results describes the outcome; knowledge of performance describes how the movement was executed.", "notes": ["Visual, verbal, manual and mechanical guidance have different uses and limitations. Manual/mechanical support may assist safety or movement experience but can create dependency if overused. Feedback can be intrinsic or extrinsic, positive or corrective. Match feedback to the learning stage: a score alone does not tell a novice what to change, while excessive instructions can overload attention.", "Distance is knowledge of results; release-angle feedback is knowledge of performance. Corrective feedback can be constructive rather than simply discouraging. Plan opportunities for the learner to judge the movement before receiving external information."], "worked": "A throw lands short. The coach says the release angle was too low.", "question": "Distinguish knowledge of results and performance using a swimming turn, and explain one benefit of each.", "scheme": ["Turn time is an outcome and provides knowledge of results.", "It indicates whether performance met the target.", "Feedback on foot placement or push-off alignment is knowledge of performance.", "It identifies a technical feature the swimmer can change."], "checks": [{"q": "Which statement is accurate?", "opts": ["Knowledge of performance is just the final score.", "Manual guidance should be used continuously with every expert.", "Knowledge of results describes the outcome; knowledge of performance describes how the movement was executed."], "a": 2, "why": "Knowledge of results describes the outcome; knowledge of performance describes how the movement was executed. Distance is knowledge of results; release-angle feedback is knowledge of performance. Corrective feedback can be constructive rather than simply discouraging. Plan opportunities for the learner to judge the movement before receiving external information."}], "animation": null}, {"id": "memory-processing", "unit": "skill", "title": "Information processing and working memory", "ref": "3.1.2.5.1–2", "summary": "Selective attention helps prioritise relevant cues before a response is selected and executed.", "notes": ["Information processing involves input, perception, decision making, output and feedback, with memory informing decisions. Whiting’s model distinguishes display, sensory organs, perceptual mechanism, translatory mechanism, effector mechanism and muscular output. Baddeley and Hitch’s working-memory model includes a central executive coordinating limited attention, a phonological loop and a visuospatial sketchpad. Later extensions include an episodic buffer. Long-term memory stores learned knowledge and skills.", "Selective attention filters the display; perception interprets the cue; the translatory mechanism selects a response. Chunking can organise related cues and reduce processing load, but attention and working-memory capacity remain limited. Describe a model as an explanatory framework rather than a literal sequence of labelled brain boxes."], "worked": "A goalkeeper notices the striker’s body position and chooses a response despite crowd noise.", "question": "Use an information-processing model to explain a tennis player responding to a wide serve.", "scheme": ["Sensory input provides information about the ball and server.", "Selective attention/perception identifies relevant direction and speed cues.", "Decision/translation selects a suitable return using memory.", "Effector output activates movement, with feedback informing later adjustment."], "checks": [{"q": "Which statement is accurate?", "opts": ["The translatory mechanism is the muscle contraction itself.", "Selective attention helps prioritise relevant cues before a response is selected and executed.", "Working memory has unlimited capacity for every simultaneous cue."], "a": 1, "why": "Selective attention helps prioritise relevant cues before a response is selected and executed. Selective attention filters the display; perception interprets the cue; the translatory mechanism selects a response. Chunking can organise related cues and reduce processing load, but attention and working-memory capacity remain limited. Describe a model as an explanatory framework rather than a literal sequence of labelled brain boxes."}], "animation": null}, {"id": "response-schema", "unit": "skill", "title": "Response time, anticipation and schema", "ref": "3.1.2.5.2", "summary": "Response time combines reaction time and movement time.", "notes": ["Reaction time runs from stimulus onset to movement initiation; movement time runs from initiation to completion. Hick’s law relates increased response alternatives to longer choice reaction time. Temporal anticipation concerns when an event occurs and spatial anticipation where. Closely spaced stimuli may delay the second response through a psychological refractory period, consistent with a processing bottleneck. Schema theory links initial conditions, response specifications, sensory consequences and outcomes to adaptable rules.", "Anticipation may reduce apparent response delay but creates a risk of selecting the wrong action. Variable practice gives varied experiences from which recall and recognition schemas can develop. A schema is an adaptable rule, not a separate stored programme for every possible pass."], "worked": "A defender moves early after reading an attacker’s approach, but a disguised change of direction makes that anticipation wrong.", "question": "A player’s reaction time is 0.22 s and movement time 0.31 s. Calculate response time and explain how a convincing feint could increase delay.", "scheme": ["Response time = reaction time + movement time.", "0.22 + 0.31 = 0.53 s.", "A feint presents competing or closely spaced response demands.", "A processing bottleneck/psychological refractory period can delay the response to the second cue."], "checks": [{"q": "Which statement is accurate?", "opts": ["Response time combines reaction time and movement time.", "Reaction time and response time always mean the same interval.", "More possible responses always makes choice reaction time shorter."], "a": 0, "why": "Response time combines reaction time and movement time. Anticipation may reduce apparent response delay but creates a risk of selecting the wrong action. Variable practice gives varied experiences from which recall and recognition schemas can develop. A schema is an adaptable rule, not a separate stored programme for every possible pass."}], "animation": null}, {"id": "popular-recreation", "unit": "society", "title": "Popular recreation before industrialisation", "ref": "3.1.3.1.1", "summary": "Pre-industrial sporting recreation reflected local conditions and a strongly divided society.", "notes": ["Before industrialisation, recreation was shaped by rural life, limited transport and communication, widespread illiteracy and harsh working conditions. Mob football often used local rules and festivals, while real tennis was associated with elite facilities and resources. A two-tier class structure affected access and status. Use these as broad historical patterns, while recognising variation between places and periods.", "Local rules and irregular festival opportunities fit popular recreation. Limited communication made uniform rules harder to spread. Compare this with elite access to real tennis rather than claiming every person in the period played the same games."], "worked": "Two villages play a festival game with locally agreed boundaries and no national governing body.", "question": "Explain two ways pre-industrial social conditions shaped mob football.", "scheme": ["Limited transport/communication encouraged local rather than national organisation.", "Rules could vary between communities.", "Harsh working patterns limited regular leisure.", "Festival occasions therefore provided opportunities for irregular large-scale recreation."], "checks": [{"q": "Which statement is accurate?", "opts": ["Pre-industrial mob football used one nationally administered rulebook.", "Real tennis and mob football were equally accessible to all social classes.", "Pre-industrial sporting recreation reflected local conditions and a strongly divided society."], "a": 2, "why": "Pre-industrial sporting recreation reflected local conditions and a strongly divided society. Local rules and irregular festival opportunities fit popular recreation. Limited communication made uniform rules harder to spread. Compare this with elite access to real tennis rather than claiming every person in the period played the same games."}], "animation": null}, {"id": "rational-recreation", "unit": "society", "title": "Industrialisation and rational recreation", "ref": "3.1.3.1.2", "summary": "Modern organised sport developed through interacting social, institutional and technological changes.", "notes": ["Urbanisation concentrated populations; factories and later leisure reforms shaped time for recreation. Railways and communication enabled fixtures and common rules. Public schools and universities helped codify sports; churches, employers and local authorities provided clubs or facilities. A growing middle class helped administration and governing bodies. These processes supported association football, lawn tennis and standardised athletics, alongside continuing inequalities.", "Transport connects directly to competition and standardisation rather than being a stand-alone historical fact. The British Empire contributed to sport’s diffusion but did not create equal power or opportunity. The Wenlock Olympian Games contributed to organised athletics and the wider revival of Olympian ideas."], "worked": "A railway allows clubs to travel for regular fixtures, increasing the need for agreed rules.", "question": "Explain how improved transport and governing bodies together supported association football’s development.", "scheme": ["Rail travel made inter-town fixtures more practical.", "More regular competition exposed problems from different local rules.", "Governing bodies codified rules and organised competitions.", "Common rules and wider fixtures supported a larger, more coherent sport."], "checks": [{"q": "Which statement is accurate?", "opts": ["Governing bodies made common rules less likely.", "Modern organised sport developed through interacting social, institutional and technological changes.", "The Industrial Revolution immediately gave every worker abundant leisure."], "a": 1, "why": "Modern organised sport developed through interacting social, institutional and technological changes. Transport connects directly to competition and standardisation rather than being a stand-alone historical fact. The British Empire contributed to sport’s diffusion but did not create equal power or opportunity. The Wenlock Olympian Games contributed to organised athletics and the wider revival of Olympian ideas."}], "animation": null}, {"id": "amateur-professional", "unit": "society", "title": "Amateurism, professionalism and women’s opportunities", "ref": "3.1.3.1.2–3", "summary": "Amateur and professional status reflected social values and access to money as well as payment rules.", "notes": ["Amateur ideals emphasised participation without payment, historically favouring people able to afford leisure. Professionalism enabled payment but could carry class stigma. Football, tennis and athletics followed different timelines and regulations. Women’s access was shaped by stereotypes, education, facilities, organisational restrictions, media and role models. Explain changing opportunities with specific mechanisms rather than assuming steady equal progress.", "A formally equal amateur rule can have unequal class effects. Increased female visibility and investment can support opportunity, yet coverage, facilities and leadership access can remain uneven. Distinguish the historical pattern from the position of every current participant."], "worked": "A skilled worker cannot afford unpaid travel while an independently wealthy competitor can.", "question": "Explain why an amateur-only competition could create a barrier for a talented working-class athlete.", "scheme": ["Amateur rules limit payment for participation.", "Travel, equipment and time away from work still have costs.", "A low-income athlete may be unable to absorb those costs.", "More affluent competitors can therefore gain access despite the same formal rule."], "checks": [{"q": "Which statement is accurate?", "opts": ["Amateur and professional status reflected social values and access to money as well as payment rules.", "Amateur status has always guaranteed equal class access.", "Women’s sporting opportunities changed identically in every sport."], "a": 0, "why": "Amateur and professional status reflected social values and access to money as well as payment rules. A formally equal amateur rule can have unequal class effects. Increased female visibility and investment can support opportunity, yet coverage, facilities and leadership access can remain uneven. Distinguish the historical pattern from the position of every current participant."}], "animation": null}, {"id": "golden-triangle", "unit": "society", "title": "Post-war sport and the golden triangle", "ref": "3.1.3.1.3", "summary": "Sport, media and commercial sponsorship influence one another.", "notes": ["Broadcast and digital audiences make sport attractive to sponsors. Sponsorship and rights income can fund performers, competitions and facilities; sporting success and spectacle attract audiences. Media can influence scheduling, presentation and rule changes. Association football, tennis and athletics offer different commercial opportunities, and investment is uneven between sports, events and genders.", "Increased revenue may improve provision, but changed scheduling can inconvenience local spectators or performers. Develop the benefit and cost for a named stakeholder. The golden triangle is reciprocal, not a claim that media alone determines every sporting decision."], "worked": "A broadcaster requests an evening fixture to reach a larger audience, helping attract sponsors.", "question": "Analyse one benefit and one possible drawback of a tennis tournament selling broadcast rights.", "scheme": ["Rights income can fund facilities, prize money or player support.", "Greater visibility can attract sponsors and participants.", "Scheduling may be adapted to broadcaster priorities.", "This can conflict with performer recovery or spectator access, so benefits differ between stakeholders."], "checks": [{"q": "Which statement is accurate?", "opts": ["The golden triangle contains sport, schools and hospitals.", "Commercial income is shared equally by every sport.", "Sport, media and commercial sponsorship influence one another."], "a": 2, "why": "Sport, media and commercial sponsorship influence one another. Increased revenue may improve provision, but changed scheduling can inconvenience local spectators or performers. Develop the benefit and cost for a named stakeholder. The golden triangle is reciprocal, not a claim that media alone determines every sporting decision."}], "animation": null}, {"id": "inequality", "unit": "society", "title": "Socialisation, inequality and participation", "ref": "3.1.3.2.1", "summary": "Participation is shaped by interacting social opportunities, expectations and personal choices.", "notes": ["Primary socialisation occurs through early close relationships; secondary socialisation includes schools, peers and clubs. Social control supports expected behaviour, while social change alters opportunities and norms. Stratification concerns unequal social positions and resources. Social action approaches examine the meanings people attach to participation. Prejudice is an attitude, stereotyping a generalised assumption and discrimination unequal treatment; they are related but distinct.", "The stereotype can shape expectations and discriminatory provision, which may reduce participation. Do not infer innate lack of interest from unequal participation. Disability, ethnicity, gender and disadvantage may intersect rather than operating independently."], "worked": "A girl is told a sport is unsuitable for her and is offered fewer opportunities to practise it.", "question": "Distinguish prejudice and discrimination in a fictional club that assumes disabled people cannot compete and refuses accessible sessions.", "scheme": ["The assumption is a prejudiced attitude/stereotype.", "Refusing access or provision is discriminatory action.", "The action creates a practical barrier to participation.", "Lower attendance therefore need not indicate lack of motivation or ability."], "checks": [{"q": "Which statement is accurate?", "opts": ["Unequal participation proves fixed differences in ability.", "Participation is shaped by interacting social opportunities, expectations and personal choices.", "Prejudice and discrimination always mean exactly the same action."], "a": 1, "why": "Participation is shaped by interacting social opportunities, expectations and personal choices. The stereotype can shape expectations and discriminatory provision, which may reduce participation. Do not infer innate lack of interest from unequal participation. Disability, ethnicity, gender and disadvantage may intersect rather than operating independently."}], "animation": null}, {"id": "participation-solutions", "unit": "society", "title": "Participation barriers and community provision", "ref": "3.1.3.2.1", "summary": "A participation intervention should address an evidenced barrier and be evaluated beyond initial attendance.", "notes": ["Cost, transport, inaccessible facilities, caring responsibilities, unsafe environments, limited information and discrimination can restrict access. Solutions should match the barrier: affordable sessions alone do not solve inaccessible transport. Sport England and local/national partners support grassroots participation, while schools, councils, clubs and community organisations influence delivery. Health, fitness and social benefits depend on sustained, suitable participation.", "Price has been reduced, but transport remains a barrier. Collect attendance and retention data alongside participants’ experiences. A comparison period or group strengthens evaluation; a rise after a campaign alone cannot rule out other influences."], "worked": "A subsidised session attracts many first visits but few repeat visits because the bus home leaves before the session ends.", "question": "Propose and justify two linked changes to improve retention at an inaccessible community sports session.", "scheme": ["Identify a specific access barrier such as transport or physical access.", "Match a practical change to that barrier.", "Identify a second barrier such as timing, cost or welcoming provision and address it.", "Evaluate repeat attendance and user feedback rather than only registrations."], "checks": [{"q": "Which statement is accurate?", "opts": ["A participation intervention should address an evidenced barrier and be evaluated beyond initial attendance.", "One free taster session guarantees permanent participation.", "Every underrepresented group faces exactly the same barriers."], "a": 0, "why": "A participation intervention should address an evidenced barrier and be evaluated beyond initial attendance. Price has been reduced, but transport remains a barrier. Collect attendance and retention data alongside participants’ experiences. A comparison period or group strengthens evaluation; a rise after a campaign alone cannot rule out other influences."}], "animation": null}, {"id": "nutrition", "unit": "exercise", "title": "Nutrition and hydration for performance", "ref": "3.2.1.1", "summary": "Food classes make different contributions to energy supply, repair and physiological function.", "notes": ["Carbohydrate supports glycogen and high-intensity fuel; fat supports energy storage and prolonged aerobic supply; protein supports repair and adaptation. Fibre supports digestive health. Iron supports haemoglobin, calcium and vitamin D support bone health, sodium contributes to fluid balance, vitamin C supports tissue maintenance and iron absorption, and B vitamins support metabolic processes. Hydration influences circulating volume and thermoregulation. Requirements vary by performer and conditions.", "Reduced carbohydrate availability can limit a high sustainable work rate even when fat stores remain. A balanced account links the nutrient to its function. This lesson explains physiology; it does not prescribe an individual diet or supplementation plan."], "worked": "An endurance athlete starts a prolonged event with low glycogen availability.", "question": "Explain why carbohydrate and iron have different roles in supporting a distance runner.", "scheme": ["Carbohydrate supplies glucose/glycogen for ATP resynthesis.", "Adequate availability helps sustain exercise intensity.", "Iron is a component needed for haemoglobin.", "Haemoglobin supports oxygen carriage for aerobic metabolism rather than serving as the runner’s main fuel."], "checks": [{"q": "Which statement is accurate?", "opts": ["Protein is the only fuel used during endurance exercise.", "Iron supplies ATP directly in place of oxygen.", "Food classes make different contributions to energy supply, repair and physiological function."], "a": 2, "why": "Food classes make different contributions to energy supply, repair and physiological function. Reduced carbohydrate availability can limit a high sustainable work rate even when fat stores remain. A balanced account links the nutrient to its function. This lesson explains physiology; it does not prescribe an individual diet or supplementation plan."}], "animation": null}, {"id": "supplements", "unit": "exercise", "title": "Dietary manipulation and supplements", "ref": "3.2.1.1", "summary": "Potential supplement benefits depend on event demands and must be weighed against limitations and risks.", "notes": ["Creatine can increase phosphocreatine availability and may support repeated high-intensity efforts, but benefits vary and body-mass changes may be undesirable. Sodium bicarbonate buffers acidity but may cause gastrointestinal discomfort. Caffeine can affect alertness and perceived effort but can disturb sleep or cause unwanted effects. Glycogen loading aims to increase carbohydrate stores for prolonged events. None removes the need for training and recovery.", "Evaluate the performance effect and the adverse effect together. Check the population, event and dose conditions before generalising. Products can be contaminated or mislabelled; performers must use current anti-doping guidance. This is critical evaluation of syllabus examples, not a recommendation to use them."], "worked": "A supplement helps repeated sprint performance in one study but the participant experiences stomach discomfort.", "question": "Evaluate a claim that creatine must improve every athlete’s performance.", "scheme": ["Creatine may increase phosphocreatine availability.", "This can help repeated short high-intensity efforts.", "Benefits may be less relevant to an event with different demands.", "Individual response and possible mass/side-effect or product-quality concerns mean improvement is not universal."], "checks": [{"q": "Which statement is accurate?", "opts": ["Glycogen loading replaces the need for carbohydrate metabolism.", "Potential supplement benefits depend on event demands and must be weighed against limitations and risks.", "Every legal supplement is guaranteed to be risk-free."], "a": 1, "why": "Potential supplement benefits depend on event demands and must be weighed against limitations and risks. Evaluate the performance effect and the adverse effect together. Check the population, event and dose conditions before generalising. Products can be contaminated or mislabelled; performers must use current anti-doping guidance. This is critical evaluation of syllabus examples, not a recommendation to use them."}], "animation": null}, {"id": "fitness-testing", "unit": "exercise", "title": "Fitness testing and interpreting data", "ref": "3.2.1.2", "summary": "A reliable test gives consistent results; a valid test measures the intended quality.", "notes": ["Quantitative data are numerical; qualitative data describe qualities or experiences. Objective measures reduce judgement dependence, while subjective ratings involve interpretation. Standardised conditions, calibrated equipment, familiarisation and repeated trials improve reliability. Validity requires a test that matches the relevant component and sporting context. Field tests offer practicality; laboratory tests offer control but may represent competition less closely.", "Consistency does not establish validity for endurance. Error, environment, motivation and learning effects can alter results. Analyse change relative to normal variability and use the same protocol rather than treating every tiny improvement as a training effect."], "worked": "A stopwatch produces similar sprint times each week, but the test is used as the only measure of endurance fitness.", "question": "Explain two controls that would improve comparison of a player’s sprint test before and after training.", "scheme": ["Use the same distance, start protocol and timing method.", "This limits measurement/procedural differences.", "Standardise surface, warm-up and recovery conditions as far as practical.", "Repeated trials/familiarisation reduce random error and learning effects."], "checks": [{"q": "Which statement is accurate?", "opts": ["A reliable test gives consistent results; a valid test measures the intended quality.", "Reliability proves a test measures the intended component.", "Qualitative data are always useless for evaluating performance."], "a": 0, "why": "A reliable test gives consistent results; a valid test measures the intended quality. Consistency does not establish validity for endurance. Error, environment, motivation and learning effects can alter results. Analyse change relative to normal variability and use the same protocol rather than treating every tiny improvement as a training effect."}], "animation": null}, {"id": "training-principles", "unit": "exercise", "title": "Training principles and methods", "ref": "3.2.1.2", "summary": "Training must match the target adaptation and provide progressive demand with sufficient recovery.", "notes": ["Specificity links training to the event’s muscles, actions and energy demands. Progressive overload increases demand over time; reversibility describes losses when stimulus is removed. FITT concerns frequency, intensity, time and type. Continuous/fartlek work can develop aerobic capacity; intervals/HIIT manipulate effort and rest; circuits can target muscular endurance, weights strength and PNF flexibility. Adaptations depend on design, not simply a method’s name.", "Aerobic capacity is useful for recovery, but a programme also needs specificity to repeated high-intensity actions. Manipulate work/rest and progression rather than merely adding more total exercise. Altitude training aims to stimulate oxygen-transport adaptations but has logistical and individual-response limitations; SAQ and plyometrics target movement speed and explosive function."], "worked": "A football player does only slow continuous running but wants to improve repeated sprint ability.", "question": "Justify two principles when designing training to improve a basketball player’s repeated jumps.", "scheme": ["Specificity: use suitable explosive lower-limb actions matched to jumping demands.", "Explain the link to force/power rather than just naming the activity.", "Progressive overload: gradually increase an appropriate demand such as quality repetitions.", "Include recovery to permit adaptation and maintain movement quality."], "checks": [{"q": "Which statement is accurate?", "opts": ["Progressive overload means making every session maximal without rest.", "The name HIIT guarantees the same adaptation for every programme.", "Training must match the target adaptation and provide progressive demand with sufficient recovery."], "a": 2, "why": "Training must match the target adaptation and provide progressive demand with sufficient recovery. Aerobic capacity is useful for recovery, but a programme also needs specificity to repeated high-intensity actions. Manipulate work/rest and progression rather than merely adding more total exercise. Altitude training aims to stimulate oxygen-transport adaptations but has logistical and individual-response limitations; SAQ and plyometrics target movement speed and explosive function."}], "animation": null}, {"id": "periodisation", "unit": "exercise", "title": "Periodisation, preparation and recovery", "ref": "3.2.1.2", "summary": "Periodisation organises training demands over time to target readiness for competition.", "notes": ["A macrocycle is a long planning period, divided into mesocycles with a particular emphasis and microcycles of shorter training/recovery organisation. Preparation, competition and transition phases have different priorities. Tapering reduces training load before an important event while retaining appropriate intensity, aiming to reduce fatigue without losing adaptations. A warm-up prepares cardiovascular, neural and movement systems; a cool-down provides a gradual transition.", "The taper aims to allow recovery while preserving event-specific readiness; it does not guarantee a personal best. Static, dynamic/active, passive and ballistic stretching differ, and suitability depends on the task and timing. Plan recovery, sleep and nutrition alongside training rather than treating them as optional extras."], "worked": "A runner reduces total work before a championship but retains some short fast efforts.", "question": "Explain why a taper may reduce training volume without eliminating all intensity before a major race.", "scheme": ["Reduced volume helps accumulated fatigue decline.", "Recovery supports readiness at the target competition.", "Retained appropriate intensity preserves event-specific neuromuscular/metabolic stimulus.", "Stopping all training for too long risks loss of readiness or reversibility."], "checks": [{"q": "Which statement is accurate?", "opts": ["A microcycle must describe an athlete’s whole career.", "Periodisation organises training demands over time to target readiness for competition.", "A taper always requires complete inactivity for several weeks."], "a": 1, "why": "Periodisation organises training demands over time to target readiness for competition. The taper aims to allow recovery while preserving event-specific readiness; it does not guarantee a personal best. Static, dynamic/active, passive and ballistic stretching differ, and suitability depends on the task and timing. Plan recovery, sleep and nutrition alongside training rather than treating them as optional extras."}], "animation": null}, {"id": "injury-rehabilitation", "unit": "exercise", "title": "Injury prevention, rehabilitation and recovery", "ref": "3.2.1.3", "summary": "Injury prevention and rehabilitation should match the mechanism, tissue and stage of recovery.", "notes": ["Acute injuries include fractures, dislocations, strains and sprains; chronic problems include stress fractures, Achilles tendinopathy and tennis elbow. Screening, suitable equipment, warm-up and managed training load can reduce risk but cannot eliminate it. Rehabilitation can use progressive strength and proprioceptive work, with water-based activity reducing loading in some settings. Hyperbaric oxygen increases oxygen availability under pressure, while cold therapies alter temperature and pain responses; effects and suitability vary.", "Proprioceptive and movement-control work may be relevant alongside strength. Massage, compression, foam rolling and cold-water approaches are recovery methods to evaluate, not interchangeable cures. A return-to-play decision requires appropriate professional assessment; pain relief alone does not establish tissue readiness."], "worked": "An athlete regains strength after an ankle injury but still struggles to control a single-leg landing.", "question": "Distinguish an acute sprain from a stress fracture and explain why rehabilitation must be progressive.", "scheme": ["A sprain is an acute ligament injury associated with a particular event.", "A stress fracture commonly reflects repeated loading over time.", "Rehabilitation must progressively restore relevant strength/control and tolerate load.", "Returning immediately to full demands can exceed current tissue/function capacity."], "checks": [{"q": "Which statement is accurate?", "opts": ["Injury prevention and rehabilitation should match the mechanism, tissue and stage of recovery.", "A strain is always a bone injury.", "If a recovery method reduces pain, full competitive readiness is guaranteed."], "a": 0, "why": "Injury prevention and rehabilitation should match the mechanism, tissue and stage of recovery. Proprioceptive and movement-control work may be relevant alongside strength. Massage, compression, foam rolling and cold-water approaches are recovery methods to evaluate, not interchangeable cures. A return-to-play decision requires appropriate professional assessment; pain relief alone does not establish tissue readiness."}], "animation": null}, {"id": "newton-stability", "unit": "biomechanics", "title": "Newton’s laws, centre of mass and stability", "ref": "3.2.2.1", "summary": "Acceleration depends on resultant external force and mass, while stability depends on support and centre-of-mass position.", "notes": ["Inertia is resistance to a change in motion. Newton’s second law is resultant force = mass × acceleration. Action–reaction pairs are equal and opposite forces acting on different bodies, so they do not cancel on one body’s force diagram. A lower centre of mass, broader support base and line of gravity within that base generally improve static stability. Mass also influences resistance to disturbance.", "A broader support base and lower centre of mass can increase stability, but mobility may be reduced. The ground reaction on the player and the player’s force on the ground act on different bodies. Analyse the resultant on the chosen body rather than subtracting an action–reaction pair."], "worked": "A rugby player widens their stance and lowers their body before a controlled contact.", "question": "A 70 kg sprinter experiences a horizontal resultant force of 210 N. Calculate acceleration and identify the third-law partner of their push on the ground.", "scheme": ["Use a = F/m.", "210/70 = 3.0 m s⁻².", "The ground exerts an equal and opposite force on the sprinter.", "The paired forces act on different bodies, so they do not cancel in the sprinter’s force total."], "checks": [{"q": "Which statement is accurate?", "opts": ["Action–reaction forces act on the same body and always cancel its acceleration.", "A higher centre of mass always improves static stability.", "Acceleration depends on resultant external force and mass, while stability depends on support and centre-of-mass position."], "a": 2, "why": "Acceleration depends on resultant external force and mass, while stability depends on support and centre-of-mass position. A broader support base and lower centre of mass can increase stability, but mobility may be reduced. The ground reaction on the player and the player’s force on the ground act on different bodies. Analyse the resultant on the chosen body rather than subtracting an action–reaction pair."}], "animation": null}, {"id": "levers", "unit": "biomechanics", "title": "Levers and mechanical advantage", "ref": "3.2.2.2", "summary": "Mechanical advantage equals effort arm divided by resistance arm.", "notes": ["First-class levers have the fulcrum between effort and resistance, second-class have resistance in the middle and third-class have effort in the middle. Examples include neck extension at the atlanto-occipital joint, a calf raise about the toes, and elbow flexion with biceps. Arms are perpendicular distances from the pivot to each force’s line of action. A third-class lever typically sacrifices force advantage for movement speed/range.", "Resistance moment is 30 N m, so balancing effort is 600 N. Mechanical advantage is 0.05/0.30 = 1/6: force disadvantage. The limb can still be effective because speed and range at the load may be valuable. The model simplifies distributed segment mass and changing muscle moment arms."], "worked": "A resistance of 100 N acts 0.30 m from a pivot, while effort acts 0.05 m away.", "question": "A resistance of 60 N acts 0.25 m from a pivot and effort acts 0.05 m away. Calculate balancing effort and mechanical advantage.", "scheme": ["Balance moments: effort × 0.05 = 60 × 0.25.", "Effort = 300 N.", "Mechanical advantage = 0.05/0.25 = 0.20.", "This is a force disadvantage: effort exceeds resistance."], "checks": [{"q": "Which statement is accurate?", "opts": ["Lever arms are measured from the end of the limb regardless of the force line.", "Mechanical advantage equals effort arm divided by resistance arm.", "A third-class lever always multiplies force above the effort."], "a": 1, "why": "Mechanical advantage equals effort arm divided by resistance arm. Resistance moment is 30 N m, so balancing effort is 600 N. Mechanical advantage is 0.05/0.30 = 1/6: force disadvantage. The limb can still be effective because speed and range at the load may be valuable. The model simplifies distributed segment mass and changing muscle moment arms."}], "animation": "lever"}, {"id": "linear-motion", "unit": "biomechanics", "title": "Linear motion and force diagrams", "ref": "3.2.2.3", "summary": "Distance and speed are scalars; displacement and velocity include direction.", "notes": ["Average speed is distance/time, velocity is displacement/time and acceleration is change in velocity/time. Momentum equals mass × velocity. Weight is the gravitational force mg, while mass measures inertia. Friction and drag depend on the situation; internal muscle forces do not alone change whole-body centre-of-mass momentum without external interaction. Read the gradient of displacement–time as velocity and velocity–time as acceleration.", "Distance is one lap but displacement is zero, so average speed is positive while average velocity is zero over the complete lap. Draw external forces on the runner separately from the forces the runner exerts on the ground. Use SI units and a stated positive direction."], "worked": "A runner completes a lap and returns to the start.", "question": "A 60 kg runner increases forward velocity from 2 to 6 m s⁻¹ in 2 s. Calculate acceleration and change in momentum.", "scheme": ["Acceleration = (6−2)/2.", "Acceleration = 2 m s⁻² forwards.", "Change in momentum = 60 × (6−2).", "Change in momentum = 240 kg m s⁻¹ forwards."], "checks": [{"q": "Which statement is accurate?", "opts": ["Distance and speed are scalars; displacement and velocity include direction.", "Returning to the start makes total distance zero.", "Mass and weight have the same unit."], "a": 0, "why": "Distance and speed are scalars; displacement and velocity include direction. Distance is one lap but displacement is zero, so average speed is positive while average velocity is zero over the complete lap. Draw external forces on the runner separately from the forces the runner exerts on the ground. Use SI units and a stated positive direction."}], "animation": null}, {"id": "impulse", "unit": "biomechanics", "title": "Impulse and force–time graphs", "ref": "3.2.2.3", "summary": "Impulse is the area under a resultant force–time graph and equals change in momentum.", "notes": ["For constant resultant force, impulse = force × time. A triangular pulse has half base × height; a varying graph requires the total signed area. Impulse has units N s, equivalent to kg m s⁻¹. A larger forward impulse can increase take-off or sprint momentum; spreading a required stopping impulse over longer time reduces average force. Specify whether a graph shows resultant force or a component such as ground reaction.", "Its impulse is ½ × 800 × 0.20 = 80 N s. If a graph instead shows vertical ground reaction, weight must be accounted for when calculating vertical momentum change. Peak force alone does not establish impulse."], "worked": "A triangular horizontal resultant-force pulse peaks at 800 N over 0.20 s.", "question": "A triangular horizontal resultant-force pulse peaks at 1000 N and lasts 0.16 s. Calculate impulse and the velocity change for an 80 kg athlete.", "scheme": ["Area = ½ × 1000 × 0.16.", "Impulse = 80 N s.", "Impulse = mass × change in velocity.", "Change in velocity = 80/80 = 1.0 m s⁻¹ in the force direction."], "checks": [{"q": "Which statement is accurate?", "opts": ["Impulse depends only on peak force.", "Area under a force–time graph gives acceleration directly.", "Impulse is the area under a resultant force–time graph and equals change in momentum."], "a": 2, "why": "Impulse is the area under a resultant force–time graph and equals change in momentum. Its impulse is ½ × 800 × 0.20 = 80 N s. If a graph instead shows vertical ground reaction, weight must be accounted for when calculating vertical momentum change. Peak force alone does not establish impulse."}], "animation": null}, {"id": "angular-motion", "unit": "biomechanics", "title": "Angular motion and conservation", "ref": "3.2.2.4", "summary": "With negligible external torque, reducing moment of inertia increases angular velocity.", "notes": ["Angular displacement measures rotation, angular velocity its rate and angular acceleration the rate of change of angular velocity. Torque changes angular momentum; moment of inertia depends on how mass is distributed about the rotation axis. During flight an athlete can change body shape while total angular momentum is approximately conserved if external torque is negligible. Drawing limbs closer reduces moment of inertia, increasing rotation rate.", "Tucking reduces moment of inertia and increases angular velocity; opening increases inertia and slows rotation. Angular momentum is not created by tucking. External torque during take-off establishes the initial rotation, so take-off and flight must be analysed separately."], "worked": "A diver tucks during a somersault and opens out before entry.", "question": "Explain how a gymnast can rotate faster in flight without increasing total angular momentum.", "scheme": ["External torque in flight is assumed negligible.", "Angular momentum is approximately conserved.", "Tucking brings mass closer to the rotation axis and reduces moment of inertia.", "Angular velocity increases so the product Iω remains approximately constant."], "checks": [{"q": "Which statement is accurate?", "opts": ["Moment of inertia depends only on total mass and never its distribution.", "With negligible external torque, reducing moment of inertia increases angular velocity.", "Tucking creates new angular momentum without external torque."], "a": 1, "why": "With negligible external torque, reducing moment of inertia increases angular velocity. Tucking reduces moment of inertia and increases angular velocity; opening increases inertia and slows rotation. Angular momentum is not created by tucking. External torque during take-off establishes the initial rotation, so take-off and flight must be analysed separately."}], "animation": "rotation"}, {"id": "projectile-motion", "unit": "biomechanics", "title": "Projectile motion in sport", "ref": "3.2.2.5", "summary": "Release speed, angle and height influence projectile range; air resistance can change the flight path.", "notes": ["In an ideal model, horizontal velocity remains constant and vertical acceleration is gravitational. Resolve release velocity into horizontal and vertical components. At equal release/landing height with fixed speed and no drag, 45° maximises range, but different release heights, speed–angle relationships and aerodynamic forces alter the optimum. A shuttle’s drag produces a very different path from a simple parabola.", "Their ideal equal-height ranges match because sin(2θ) is equal, but flight times and peak heights differ. Real performers may release at different speeds as angle changes. Label model assumptions and avoid applying 45° as a universal coaching rule."], "worked": "Two ideal projectiles leave the same height at the same speed, one at 30° and one at 60°.", "question": "Explain why the best release angle for a real shot put need not be 45°.", "scheme": ["The 45° result assumes fixed speed, equal heights and negligible air resistance.", "A shot is normally released above its landing height.", "The performer’s achievable release speed may vary with angle.", "These changes affect range and mean the ideal equal-height result is not a universal optimum."], "checks": [{"q": "Which statement is accurate?", "opts": ["Release speed, angle and height influence projectile range; air resistance can change the flight path.", "Every sporting projectile must have a 45° optimal release angle.", "Gravity acts only after a projectile reaches its highest point."], "a": 0, "why": "Release speed, angle and height influence projectile range; air resistance can change the flight path. Their ideal equal-height ranges match because sin(2θ) is equal, but flight times and peak heights differ. Real performers may release at different speeds as angle changes. Label model assumptions and avoid applying 45° as a universal coaching rule."}], "animation": "projectile"}, {"id": "fluid-mechanics", "unit": "biomechanics", "title": "Drag, lift and the Bernoulli principle", "ref": "3.2.2.6", "summary": "Fluid forces depend on relative flow and body shape, and can assist or hinder performance.", "notes": ["Drag opposes relative motion through a fluid; streamlining and suitable surfaces can reduce it. Increasing frontal area can increase drag where slowing is useful. Lift is perpendicular to relative flow and can act upward or downward. Pressure differences associated with flow can contribute to lift; Bernoulli’s principle relates speed and pressure under stated ideal flow conditions. Do not use the false claim that separated air particles must meet again at the same time.", "Different goals require different drag choices. A discus can experience lift, while downward aerodynamic force can improve grip in relevant racing contexts. Real fluid flow is complex: angle, turbulence and rotation matter, so a single ideal equation does not fully describe every technique."], "worked": "A cyclist lowers their torso while a parachutist increases area to slow down.", "question": "Explain two ways a swimmer could reduce resistive drag and give one limitation of a simplified flow model.", "scheme": ["A streamlined body position reduces frontal area.", "Suitable alignment/technique reduces unnecessary disturbance and drag.", "Less resistive force can improve speed for a given propulsive effort.", "Real flow includes turbulence and changing movement, so ideal steady-flow predictions have limits."], "checks": [{"q": "Which statement is accurate?", "opts": ["Lift must always point vertically upward.", "Drag is independent of body shape and relative fluid speed.", "Fluid forces depend on relative flow and body shape, and can assist or hinder performance."], "a": 2, "why": "Fluid forces depend on relative flow and body shape, and can assist or hinder performance. Different goals require different drag choices. A discus can experience lift, while downward aerodynamic force can improve grip in relevant racing contexts. Real fluid flow is complex: angle, turbulence and rotation matter, so a single ideal equation does not fully describe every technique."}], "animation": null}, {"id": "personality", "unit": "psychology", "title": "Personality and the interactionist view", "ref": "3.2.3.1.1", "summary": "An interactionist account considers both personal characteristics and the sporting situation.", "notes": ["Trait accounts emphasise relatively stable characteristics, while social learning emphasises environmental experience and modelling. Hollander distinguishes a psychological core, typical responses and role-related behaviour. Lewin expresses behaviour as a function of person and environment. A player may act differently in training and a final without having an entirely different personality. Personality measures should not be used as deterministic labels of sporting ability.", "Role demands and context interact with personal characteristics. Coaches can adapt communication and responsibility, but should check the athlete’s actual response rather than infer it from a broad type. Behaviour in one match alone is insufficient evidence of a permanent trait."], "worked": "A normally quiet athlete becomes vocal when appointed team captain.", "question": "Use an interactionist explanation for a player who behaves calmly in practice but anxiously in a final.", "scheme": ["Personal characteristics influence likely responses.", "The final adds situational pressure/evaluation.", "Behaviour reflects interaction between these factors.", "A different context can change behaviour without proving a wholly different underlying personality."], "checks": [{"q": "Which statement is accurate?", "opts": ["Interactionism excludes the environment.", "An interactionist account considers both personal characteristics and the sporting situation.", "A personality label perfectly predicts every future performance."], "a": 1, "why": "An interactionist account considers both personal characteristics and the sporting situation. Role demands and context interact with personal characteristics. Coaches can adapt communication and responsibility, but should check the athlete’s actual response rather than infer it from a broad type. Behaviour in one match alone is insufficient evidence of a permanent trait."}], "animation": null}, {"id": "attitudes", "unit": "psychology", "title": "Attitudes and changing attitudes", "ref": "3.2.3.1.2", "summary": "The triadic model separates cognitive, affective and behavioural components of an attitude.", "notes": ["Cognitive components concern beliefs, affective components feelings and behavioural components tendencies to act. Family, peers, past experience and media can influence formation. Cognitive dissonance arises from inconsistency and may motivate change, but the person can resolve it in more than one way. Persuasive communication depends on source credibility, message and audience characteristics, not simply repetition.", "A positive belief does not guarantee positive feelings or participation. A supportive low-pressure introduction may address the affective barrier more directly than another health message. Evaluate whether behaviour actually changes rather than only asking if the message was remembered."], "worked": "A student believes exercise is beneficial but avoids a club after an embarrassing experience.", "question": "Apply all three attitude components to a pupil reluctant to join swimming lessons.", "scheme": ["Cognitive: identify a belief, such as thinking swimming is difficult.", "Affective: identify a feeling, such as embarrassment or anxiety.", "Behavioural: identify avoidance or refusal to attend.", "Explain how a targeted positive experience or credible message could address the relevant component."], "checks": [{"q": "Which statement is accurate?", "opts": ["The triadic model separates cognitive, affective and behavioural components of an attitude.", "The affective component is a person’s factual belief only.", "Persuasion guarantees immediate behaviour change."], "a": 0, "why": "The triadic model separates cognitive, affective and behavioural components of an attitude. A positive belief does not guarantee positive feelings or participation. A supportive low-pressure introduction may address the affective barrier more directly than another health message. Evaluate whether behaviour actually changes rather than only asking if the message was remembered."}], "animation": null}, {"id": "arousal", "unit": "psychology", "title": "Arousal theories and peak flow", "ref": "3.2.3.1.3", "summary": "Arousal theories make different predictions, and the most useful level depends on performer and task.", "notes": ["Drive theory predicts a stronger dominant response as arousal rises, which can help a well-learned response but strengthen errors in novices. Inverted-U theory predicts an intermediate optimum. Catastrophe theory considers interaction between physiological arousal and cognitive anxiety, with a possible sudden performance drop at high anxiety. Individual zones of optimal functioning allow different personal ranges. Flow involves absorption, clear goals and a sense of control, rather than guaranteed maximal arousal.", "The inverted-U offers a simple prediction but does not fix the same optimum for everyone. A catastrophe curve is a theoretical relationship, not a diagnostic graph of a particular student. Consider skill complexity, expertise and anxiety when making a recommendation."], "worked": "A precise shooter performs worse after becoming extremely activated, while a powerful action may tolerate higher arousal.", "question": "Compare drive theory and the inverted-U prediction for a highly aroused novice learning a complex movement.", "scheme": ["Drive theory predicts strengthening of the dominant response.", "For a novice this may strengthen an incorrect response.", "The inverted-U predicts performance falling beyond an intermediate optimum.", "Both can explain poor high-arousal performance here, but through different theoretical mechanisms."], "checks": [{"q": "Which statement is accurate?", "opts": ["Every performer’s optimum arousal is exactly the same.", "Drive theory predicts that every error disappears at high arousal.", "Arousal theories make different predictions, and the most useful level depends on performer and task."], "a": 2, "why": "Arousal theories make different predictions, and the most useful level depends on performer and task. The inverted-U offers a simple prediction but does not fix the same optimum for everyone. A catastrophe curve is a theoretical relationship, not a diagnostic graph of a particular student. Consider skill complexity, expertise and anxiety when making a recommendation."}], "animation": "arousal"}, {"id": "anxiety", "unit": "psychology", "title": "Anxiety types and measurement", "ref": "3.2.3.1.4", "summary": "Cognitive anxiety concerns worry; somatic anxiety concerns bodily responses.", "notes": ["Competitive trait anxiety is a relatively enduring tendency, while competitive state anxiety concerns a particular situation. Questionnaires can access thoughts but are affected by self-report bias and interpretation. Observation captures behaviour but not every private worry. Physiological measures can be objective indicators of activation but are not specific to anxiety: exercise itself raises heart rate.", "Pulse alone cannot establish that the player is anxious. Combine measures and context, using consistent timing. A change within a person may be more informative than comparing raw scores between people with different baselines."], "worked": "A player has a high pulse after warming up but reports feeling confident.", "question": "Evaluate using heart rate alone to measure anxiety before a match.", "scheme": ["Heart rate is measurable and can provide repeatable numerical data.", "However warm-up, temperature and other factors also affect it.", "A high rate therefore does not uniquely identify anxiety or worry.", "Combine physiological information with appropriate self-report/observation and context."], "checks": [{"q": "Which statement is accurate?", "opts": ["Trait anxiety refers only to one moment before a match.", "Cognitive anxiety concerns worry; somatic anxiety concerns bodily responses.", "High heart rate proves cognitive anxiety in every situation."], "a": 1, "why": "Cognitive anxiety concerns worry; somatic anxiety concerns bodily responses. Pulse alone cannot establish that the player is anxious. Combine measures and context, using consistent timing. A change within a person may be more informative than comparing raw scores between people with different baselines."}], "animation": null}, {"id": "aggression", "unit": "psychology", "title": "Aggression, assertion and control", "ref": "3.2.3.1.5", "summary": "Aggression involves intent to harm; assertive play can be forceful without that intent.", "notes": ["Instinct accounts, frustration–aggression ideas, social learning and aggressive-cue theories offer different explanations. Frustration does not inevitably produce aggression. Modelling and reinforcement can normalise harmful behaviour, while cues may increase the likelihood of aggression in a susceptible context. Clear conduct expectations, appropriate sanctions, role models and emotion-regulation strategies can help control behaviour.", "Force alone does not establish aggression. Conversely, harmful intent can be present even if an official misses the incident. Explain the intention and context, and avoid treating all competitive contact as unacceptable aggression."], "worked": "A player makes a forceful legal challenge to win possession without intending harm.", "question": "Distinguish assertion from aggression and apply social learning to a junior copying a professional’s violent reaction.", "scheme": ["Assertion is forceful goal-directed play without intent to harm.", "Aggression includes intent to harm.", "A visible role model can be observed and copied.", "Apparent reward or lack of consequences can reinforce the copied aggressive response."], "checks": [{"q": "Which statement is accurate?", "opts": ["Aggression involves intent to harm; assertive play can be forceful without that intent.", "Every forceful legal action is aggression.", "Frustration always causes an aggressive response."], "a": 0, "why": "Aggression involves intent to harm; assertive play can be forceful without that intent. Force alone does not establish aggression. Conversely, harmful intent can be present even if an official misses the incident. Explain the intention and context, and avoid treating all competitive contact as unacceptable aggression."}], "animation": null}, {"id": "motivation", "unit": "psychology", "title": "Intrinsic and extrinsic motivation", "ref": "3.2.3.1.6", "summary": "Extrinsic rewards can support participation but their effect depends on how they are experienced.", "notes": ["Intrinsic motivation comes from interest, enjoyment and mastery. Extrinsic motivation involves external outcomes; rewards can be tangible, such as a trophy, or intangible, such as praise. Informational praise can support perceived competence, while controlling rewards may undermine autonomy or shift attention away from enjoyment. Effects depend on the person, task and reward use.", "The reward may change the reason for participation. This does not prove all prizes are harmful: feedback that recognises effort and progress can support motivation. Evaluate sustained participation after a reward ends, not just immediate compliance."], "worked": "A child enjoys learning a skill but begins practising only when promised a prize.", "question": "Explain one possible benefit and one possible drawback of giving a young athlete prizes for attendance.", "scheme": ["Prizes can provide an external incentive to attend initially.", "Attendance can create opportunities for learning and positive experience.", "Dependence on prizes may reduce participation when rewards end.", "If experienced as controlling, rewards may reduce intrinsic enjoyment/autonomy."], "checks": [{"q": "Which statement is accurate?", "opts": ["Intrinsic motivation means working only for money.", "Every external reward inevitably destroys motivation.", "Extrinsic rewards can support participation but their effect depends on how they are experienced."], "a": 2, "why": "Extrinsic rewards can support participation but their effect depends on how they are experienced. The reward may change the reason for participation. This does not prove all prizes are harmful: feedback that recognises effort and progress can support motivation. Evaluate sustained participation after a reward ends, not just immediate compliance."}], "animation": null}, {"id": "achievement", "unit": "psychology", "title": "Achievement motivation and goals", "ref": "3.2.3.1.7", "summary": "Achievement behaviour reflects both motives and the performer’s interpretation of the task.", "notes": ["Atkinson’s model considers need to achieve and need to avoid failure alongside probability of success and incentive value. A performer high in achievement motivation may seek challenging but attainable tasks; someone focused on avoiding failure may choose very easy tasks or very hard tasks with an excuse for failure. Achievement goal theory distinguishes task/mastery orientation from outcome/ego comparison. These are useful tendencies, not fixed destinies.", "A task focus gives success criteria the athlete can influence. Coaches can develop approach behaviour through attainable progression, effort feedback and a learning climate. Avoid interpreting one cautious choice as proof of a permanent personality type."], "worked": "An athlete chooses a difficult but achievable personal technique target rather than only comparing rankings.", "question": "Explain how a coach could encourage a performer who avoids moderately challenging tasks for fear of failure.", "scheme": ["Set achievable progressive challenges with a clear success criterion.", "Emphasise task/mastery improvement rather than only ranking.", "Give feedback on controllable effort and strategy.", "This can reduce threat and support approach behaviour, though response should be monitored."], "checks": [{"q": "Which statement is accurate?", "opts": ["Outcome orientation measures only improvement against one’s own technique.", "Achievement behaviour reflects both motives and the performer’s interpretation of the task.", "A high need to achieve means selecting only tasks guaranteed to be easy."], "a": 1, "why": "Achievement behaviour reflects both motives and the performer’s interpretation of the task. A task focus gives success criteria the athlete can influence. Coaches can develop approach behaviour through attainable progression, effort feedback and a learning climate. Avoid interpreting one cautious choice as proof of a permanent personality type."}], "animation": null}, {"id": "social-facilitation", "unit": "psychology", "title": "Social facilitation and evaluation apprehension", "ref": "3.2.3.1.8", "summary": "An audience can improve or impair performance depending on the dominant response and perceived evaluation.", "notes": ["Zajonc’s account links audience presence to increased arousal and a stronger dominant response. A well-learned task can benefit, while a complex or unfamiliar task may deteriorate. Evaluation apprehension adds concern about being judged, so audience meaning matters as well as presence. Strategies include gradual exposure, familiar routines and attentional focus on relevant cues.", "The difference fits dominant-response strength, but is not a universal prediction for all athletes. A supportive crowd may still create pressure. Practise competition conditions progressively and evaluate actual effects rather than assuming that a home audience guarantees improvement."], "worked": "An experienced sprinter responds well to a crowd, while a novice loses control of a newly learned skill.", "question": "Explain why performing a new gymnastics skill in front of selectors might impair a novice’s performance.", "scheme": ["Audience/evaluation can increase arousal and apprehension.", "A novice’s dominant response may still contain errors.", "Increased arousal can strengthen that response.", "Concern about judgement can also distract attention from relevant movement cues."], "checks": [{"q": "Which statement is accurate?", "opts": ["An audience can improve or impair performance depending on the dominant response and perceived evaluation.", "An audience always improves every task.", "Evaluation apprehension means a performer cannot see the audience."], "a": 0, "why": "An audience can improve or impair performance depending on the dominant response and perceived evaluation. The difference fits dominant-response strength, but is not a universal prediction for all athletes. A supportive crowd may still create pressure. Practise competition conditions progressively and evaluate actual effects rather than assuming that a home audience guarantees improvement."}], "animation": null}, {"id": "group-dynamics", "unit": "psychology", "title": "Group formation, cohesion and productivity", "ref": "3.2.3.1.9", "summary": "Actual group productivity can fall below potential because of coordination and motivational losses.", "notes": ["Tuckman’s forming, storming, norming and performing stages describe a possible development pattern rather than a compulsory fixed timetable. Task cohesion concerns commitment to shared performance goals; social cohesion concerns relationships. Steiner’s model subtracts faulty group processes from potential productivity. Ringelmann-type effects and social loafing can involve reduced individual contribution in groups, but poor team output can also reflect coordination rather than effort alone.", "Potential ability is high, but coordination losses reduce actual output. Clear roles, shared practice and identifiable contributions can address different losses. More friendship does not automatically improve technical coordination or guarantee winning."], "worked": "A relay team contains fast runners but loses time through poorly timed exchanges.", "question": "Use Steiner’s model to explain why a talented rowing crew underperforms and suggest a matching solution.", "scheme": ["Potential productivity reflects the crew’s available ability/resources.", "Poor timing/cooperation can create coordination losses.", "Reduced individual effort can create motivational losses; do not assume which without evidence.", "Shared timing practice and identifiable roles/feedback can target the identified loss."], "checks": [{"q": "Which statement is accurate?", "opts": ["High social cohesion guarantees maximum team performance.", "Every group performance loss proves deliberate laziness.", "Actual group productivity can fall below potential because of coordination and motivational losses."], "a": 2, "why": "Actual group productivity can fall below potential because of coordination and motivational losses. Potential ability is high, but coordination losses reduce actual output. Clear roles, shared practice and identifiable contributions can address different losses. More friendship does not automatically improve technical coordination or guarantee winning."}], "animation": null}, {"id": "goal-setting", "unit": "psychology", "title": "Goal setting and SMARTER", "ref": "3.2.3.1.10", "summary": "Process and performance goals give performers targets they can control more directly than final results.", "notes": ["Outcome goals concern results relative to others, performance goals an individual standard and process goals execution behaviours. SMARTER goals are specific, measurable, achievable, realistic, time-bound, evaluated and re-done/revised. Goals can direct attention and effort but need review as circumstances change. A target that is measurable but unrealistic can undermine motivation.", "Winning is an outcome goal; a personal time is a performance goal; pacing behaviours are process goals. They can work together. Make the target appropriate to baseline and available time, then evaluate progress rather than merely adding the word SMARTER to a plan."], "worked": "A runner aims to win, improve a personal time, and maintain a specified pacing strategy.", "question": "Give one process and one performance goal for improving a swimmer’s turn and explain how each could be evaluated.", "scheme": ["A process goal identifies a controllable action such as consistent foot placement.", "Video/checklist observations evaluate whether that action occurs.", "A performance goal specifies a personal turn-time standard over a stated period.", "Standardised repeated timing evaluates progress against the swimmer’s baseline."], "checks": [{"q": "Which statement is accurate?", "opts": ["SMARTER goals never need revision.", "Process and performance goals give performers targets they can control more directly than final results.", "An outcome goal is always fully under the athlete’s control."], "a": 1, "why": "Process and performance goals give performers targets they can control more directly than final results. Winning is an outcome goal; a personal time is a performance goal; pacing behaviours are process goals. They can work together. Make the target appropriate to baseline and available time, then evaluate progress rather than merely adding the word SMARTER to a plan."}], "animation": null}, {"id": "attribution", "unit": "psychology", "title": "Attribution and learned helplessness", "ref": "3.2.3.1.11", "summary": "Attributions can affect expectations, motivation and persistence after success or failure.", "notes": ["Weiner’s model classifies perceived causes by locus, stability and controllability. Effort is often internal, unstable and controllable; perceived ability may be internal and stable, though beliefs and context affect classification. Self-serving bias assigns success and failure in self-protective ways. Repeated explanations of failure as unavoidable may contribute to specific or general learned helplessness. Attribution retraining emphasises realistic controllable explanations and strategies.", "A stable uncontrollable interpretation can reduce expectations and persistence. A coach can identify changeable preparation or technique factors without blaming the athlete for circumstances outside their control. Empty reassurance is weaker than evidence of achievable progress."], "worked": "After a poor result an athlete says, “I can never improve because I have no ability.”", "question": "Explain how attribution retraining could help a player who interprets every missed shot as permanent inability.", "scheme": ["The player attributes failure to a stable internal cause.", "This may lower future expectations and persistence.", "Use evidence to identify controllable/changeable factors such as technique or preparation.", "Set achievable actions and review improvement to develop a more adaptive realistic attribution."], "checks": [{"q": "Which statement is accurate?", "opts": ["Attributions can affect expectations, motivation and persistence after success or failure.", "All failure should be blamed on luck regardless of evidence.", "Learned helplessness guarantees identical behaviour in every life domain."], "a": 0, "why": "Attributions can affect expectations, motivation and persistence after success or failure. A stable uncontrollable interpretation can reduce expectations and persistence. A coach can identify changeable preparation or technique factors without blaming the athlete for circumstances outside their control. Empty reassurance is weaker than evidence of achievable progress."}], "animation": null}, {"id": "confidence", "unit": "psychology", "title": "Self-efficacy, confidence and home advantage", "ref": "3.2.3.1.12", "summary": "Self-efficacy concerns belief in performing a particular task, rather than global self-worth.", "notes": ["Bandura identifies performance accomplishments, vicarious experience, verbal persuasion and emotional arousal as sources of efficacy information. Self-confidence is a broader belief in success, while self-esteem concerns personal worth. Vealey links trait sport confidence, competitive orientation and the sporting situation to state sport confidence. A home setting may offer familiarity and support but can also create pressure; home advantage has multiple possible causes.", "Mastery experiences can provide strong task-specific evidence. Modelling works best when the model feels relevant; persuasion is stronger when credible. Reframing arousal may help, but confidence without skill or preparation does not guarantee performance."], "worked": "A player succeeds at progressively harder practice serves and becomes more confident about serving under match conditions.", "question": "Use two Bandura sources to suggest how a coach could build a novice’s confidence in a vault.", "scheme": ["Create safe achievable progressions that provide performance accomplishments.", "Successful steps provide evidence of capability.", "Use a relatable competent model for vicarious experience, or credible specific persuasion.", "Link the information to the particular vault rather than promising general invulnerability."], "checks": [{"q": "Which statement is accurate?", "opts": ["Self-efficacy is simply a person’s overall worth.", "Playing at home guarantees lower pressure and a win.", "Self-efficacy concerns belief in performing a particular task, rather than global self-worth."], "a": 2, "why": "Self-efficacy concerns belief in performing a particular task, rather than global self-worth. Mastery experiences can provide strong task-specific evidence. Modelling works best when the model feels relevant; persuasion is stronger when credible. Reframing arousal may help, but confidence without skill or preparation does not guarantee performance."}], "animation": null}, {"id": "leadership", "unit": "psychology", "title": "Leadership styles and contingency models", "ref": "3.2.3.1.13", "summary": "Effective leadership depends on the leader, performers and situation.", "notes": ["Autocratic leadership concentrates decisions, democratic leadership involves group input and laissez-faire leadership allows substantial independence. Leaders can be prescribed by appointment or emerge through the group. Fiedler’s contingency approach links style and situational favourableness. Chelladurai’s multidimensional model considers required, preferred and actual leader behaviour; alignment can support satisfaction and performance.", "Different demands justify different approaches. Democracy is not automatically best in every moment, and autocracy is not necessarily evidence of poor coaching. Consider expertise, urgency, group preference and task structure when recommending a style."], "worked": "A coach uses direct instructions in an urgent safety situation but involves experienced players in tactical planning.", "question": "Apply Chelladurai’s model to an experienced team that prefers consultation but receives only rigid instructions.", "scheme": ["Preferred behaviour includes athlete involvement in decisions.", "Actual behaviour is highly directive.", "Mismatch may reduce satisfaction or commitment, depending on required demands.", "A coach can consult where appropriate while retaining direction when safety/task requirements demand it."], "checks": [{"q": "Which statement is accurate?", "opts": ["An emergent leader must have been officially appointed.", "Effective leadership depends on the leader, performers and situation.", "One leadership style is optimal for every performer and situation."], "a": 1, "why": "Effective leadership depends on the leader, performers and situation. Different demands justify different approaches. Democracy is not automatically best in every moment, and autocracy is not necessarily evidence of poor coaching. Consider expertise, urgency, group preference and task structure when recommending a style."}], "animation": null}, {"id": "stress-management", "unit": "psychology", "title": "Stress management and attentional control", "ref": "3.2.3.1.14", "summary": "Stress management should match the performer’s symptoms and the task’s attentional demands.", "notes": ["A stressor is a demand; stress involves the performer’s appraisal and response. Cognitive techniques include imagery, mental rehearsal, positive self-talk, thought stopping and attentional cues. Somatic techniques include breathing control, centering, progressive muscle relaxation and biofeedback. A familiar warm-up can support preparation and regulation. Techniques require practice and individual evaluation, not use only at the most pressured moment.", "A brief task cue may redirect cognitive attention, while practised breathing or relaxation can address somatic activation. Mental rehearsal should represent a relevant task. Avoid overwhelming the performer with many new instructions or promising a technique will eliminate all anxiety."], "worked": "A player worries about missing and then rushes the movement with tense shoulders.", "question": "Justify one cognitive and one somatic technique for a worried, physically tense penalty taker.", "scheme": ["Use a practised positive/task-focused cue or imagery to redirect worry.", "Explain how it focuses attention on controllable execution.", "Use practised breathing/centering or relaxation to regulate bodily tension.", "Evaluate the athlete’s response during preparation rather than introducing an untested routine only in competition."], "checks": [{"q": "Which statement is accurate?", "opts": ["Stress management should match the performer’s symptoms and the task’s attentional demands.", "Every stressor produces exactly the same response in all athletes.", "Imagery is a form of muscle-strength training without movement."], "a": 0, "why": "Stress management should match the performer’s symptoms and the task’s attentional demands. A brief task cue may redirect cognitive attention, while practised breathing or relaxation can address somatic activation. Mental rehearsal should represent a relevant task. Avoid overwhelming the performer with many new instructions or promising a technique will eliminate all anxiety."}], "animation": null}, {"id": "activity-concepts", "unit": "contemporary", "title": "Physical recreation, PE and sport", "ref": "3.2.4.1", "summary": "Physical education, recreation and competitive sport have overlapping but different purposes.", "notes": ["Physical recreation often prioritises enjoyment, leisure and wellbeing. Sport commonly includes agreed rules, organisation and competition. Physical education has educational aims including knowledge, skills and understanding; school sport provides opportunities for organised activity and competition in an educational setting. The development continuum can connect foundation, participation, performance and excellence, without assuming everyone wishes or is able to progress towards elite competition.", "The lesson illustrates educational aims; the competition illustrates school sport. A recreational participant may value enjoyment over rankings. Classifications can overlap, so justify the dominant purpose rather than relying on the venue alone."], "worked": "A school teaches movement analysis in a lesson and also runs an inter-school competition.", "question": "Compare a recreational swim and a school PE swimming lesson in terms of purpose and possible overlap.", "scheme": ["A recreational swim can prioritise leisure/enjoyment or wellbeing.", "A PE lesson has planned educational outcomes.", "Both may develop fitness and movement competence.", "The distinction depends on purpose/structure, so the same activity can serve both functions."], "checks": [{"q": "Which statement is accurate?", "opts": ["All physical activity must aim at elite competition.", "Physical education is defined only by winning matches.", "Physical education, recreation and competitive sport have overlapping but different purposes."], "a": 2, "why": "Physical education, recreation and competitive sport have overlapping but different purposes. The lesson illustrates educational aims; the competition illustrates school sport. A recreational participant may value enjoyment over rankings. Classifications can overlap, so justify the dominant purpose rather than relying on the venue alone."}], "animation": null}, {"id": "elite-pathways", "unit": "contemporary", "title": "Talent development and elite support", "ref": "3.2.4.2", "summary": "Elite pathways require coordinated support and should not treat early selection as a perfect prediction.", "notes": ["National governing bodies organise sport-specific pathways; UK Sport supports high-performance Olympic and Paralympic systems, while institutes provide services such as sports science, medicine and performance support. Talent identification, development and competition opportunities interact. The specification names programmes such as the World Class Performance Programme and Gold Event Series, or equivalent current programmes. Distinguish programme purposes rather than assuming names or funding arrangements never change.", "Selection can be affected by maturation, opportunity and relative age. Repeated review and development support are stronger than claiming one test identifies every future champion. Grassroots participation and elite funding have different primary aims, although their systems can connect."], "worked": "A promising young athlete receives coaching, appropriate competition and multidisciplinary support rather than only a one-off fitness score.", "question": "Explain why a talent pathway should combine repeated assessment with coaching and wider support.", "scheme": ["A single result can reflect maturation, opportunity or temporary form.", "Repeated assessment tracks development more fairly.", "Coaching develops skills rather than only selecting existing performance.", "Sports science/medical and welfare support can help sustain appropriate progress."], "checks": [{"q": "Which statement is accurate?", "opts": ["UK Sport and a local grassroots club have identical primary roles.", "Elite pathways require coordinated support and should not treat early selection as a perfect prediction.", "One childhood test identifies all future elite performers without error."], "a": 1, "why": "Elite pathways require coordinated support and should not treat early selection as a perfect prediction. Selection can be affected by maturation, opportunity and relative age. Repeated review and development support are stronger than claiming one test identifies every future champion. Grassroots participation and elite funding have different primary aims, although their systems can connect."}], "animation": null}, {"id": "ethics", "unit": "contemporary", "title": "Sportsmanship, gamesmanship and deviance", "ref": "3.2.4.3", "summary": "Legal compliance and ethical sporting behaviour are related but not identical.", "notes": ["Sportsmanship involves respect, fairness and the spirit of competition. Gamesmanship seeks advantage through manipulation within or at the edge of rules; cheating breaks rules. A win ethic prioritises victory and may create ethical tensions. Positive deviance involves overconformity to sporting norms, such as competing through harmful injury; negative deviance involves rejecting accepted rules. Amateur ideals and the Olympic Oath express values, but stated values do not guarantee behaviour.", "The behaviour may illustrate gamesmanship even if no formal penalty is given. Explain the intent, rule context and effect on fair competition. Playing through injury may be praised as commitment while causing harm, illustrating why overconformity needs critical evaluation."], "worked": "A player repeatedly delays a restart to disrupt an opponent while staying just within the official’s tolerance.", "question": "Distinguish sportsmanship and gamesmanship using two original examples from a racket sport.", "scheme": ["Sportsmanship could include acknowledging an opponent’s valid point or correcting an incorrect call.", "Explain the respect/fairness shown.", "Gamesmanship could include deliberate legal disruption of an opponent’s rhythm.", "Explain the attempt to gain an advantage that conflicts with the spirit of fair play."], "checks": [{"q": "Which statement is accurate?", "opts": ["Legal compliance and ethical sporting behaviour are related but not identical.", "Every action not penalised by an official is automatically sportsmanlike.", "Positive deviance means that a harmful behaviour is medically beneficial."], "a": 0, "why": "Legal compliance and ethical sporting behaviour are related but not identical. The behaviour may illustrate gamesmanship even if no formal penalty is given. Explain the intent, rule context and effect on fair competition. Playing through injury may be praised as commitment while causing harm, illustrating why overconformity needs critical evaluation."}], "animation": null}, {"id": "violence", "unit": "contemporary", "title": "Violence in sport and prevention", "ref": "3.2.4.4", "summary": "Violence has multiple situational and social influences, so prevention needs more than one measure.", "notes": ["Performer violence may relate to frustration, norms, provocation, modelling and inadequate sanctions. Spectator incidents can involve group identity, rivalry, alcohol, crowd management and wider social context. Consequences include injury, exclusion, damaged reputation and reduced participation. Proportionate officiating, conduct education, venue design, stewarding and cooperation with relevant authorities can address different mechanisms.", "Physical management and social expectations address different risks. Avoid stereotyping every supporter or treating one factor as a universal cause. Evaluate both incident data and whether spectators feel safe, considering reporting changes."], "worked": "A venue introduces clearer stewarding routes and responds quickly to discriminatory chanting.", "question": "Suggest and explain one performer-focused and one spectator-focused strategy to reduce violence.", "scheme": ["Consistent officiating/sanctions and conduct expectations can deter performer violence.", "Explain how they change incentives or accepted norms.", "Appropriate stewarding/venue management can reduce spectator conflict opportunities.", "Education/reporting and rapid response can challenge harmful group behaviour and support safety."], "checks": [{"q": "Which statement is accurate?", "opts": ["All spectators from a particular group are inherently violent.", "One punishment eliminates every cause of violence.", "Violence has multiple situational and social influences, so prevention needs more than one measure."], "a": 2, "why": "Violence has multiple situational and social influences, so prevention needs more than one measure. Physical management and social expectations address different risks. Avoid stereotyping every supporter or treating one factor as a universal cause. Evaluate both incident data and whether spectators feel safe, considering reporting changes."}], "animation": null}, {"id": "doping", "unit": "contemporary", "title": "Doping, performance and ethical debate", "ref": "3.2.4.5", "summary": "Doping can offer a perceived performance advantage while creating health, fairness and welfare harms.", "notes": ["EPO can increase red-cell production and oxygen carriage, but excessive changes can increase cardiovascular risk. Anabolic agents can support muscle-building processes but carry significant health harms. Beta blockers reduce sympathetic effects such as tremor and heart rate, with sport-specific anti-doping restrictions. Pressure, reward, social norms and fear of losing selection can influence decisions. Evaluate education, deterrence, testing and support; check current official prohibited-list guidance rather than assuming all substances have identical rules.", "Perceived unfair competition can encourage a coercive cycle, but does not remove ethical responsibility. Sanctions, welfare harms and loss of trust affect both performer and sport. A balanced debate should address fairness and autonomy without treating drug use as a safe training strategy; testing procedures themselves are outside this specification’s examined detail."], "worked": "An endurance performer is pressured to use a banned substance because rivals may be doing so.", "question": "Explain an intended physiological effect and two wider consequences of an endurance performer using EPO illicitly.", "scheme": ["EPO can stimulate red-cell production and increase oxygen-carrying capacity.", "This may support aerobic performance.", "Health risks can include harmful effects of increased blood viscosity/cardiovascular strain.", "Bans, reputational damage and reduced fairness/trust can harm performer and sport."], "checks": [{"q": "Which statement is accurate?", "opts": ["Every prohibited substance has exactly the same sporting effect.", "Doping can offer a perceived performance advantage while creating health, fairness and welfare harms.", "EPO improves oxygen carriage without any potential health risk."], "a": 1, "why": "Doping can offer a perceived performance advantage while creating health, fairness and welfare harms. Perceived unfair competition can encourage a coercive cycle, but does not remove ethical responsibility. Sanctions, welfare harms and loss of trust affect both performer and sport. A balanced debate should address fairness and autonomy without treating drug use as a safe training strategy; testing procedures themselves are outside this specification’s examined detail."}], "animation": null}, {"id": "sport-law", "unit": "contemporary", "title": "Sport, law and duty of care", "ref": "3.2.4.6", "summary": "Sporting rules do not remove wider responsibilities concerning safety, contracts and care.", "notes": ["Performers may encounter contracts, injury claims and loss of earnings; officials and coaches have responsibilities relevant to negligence and duty of care; venue operators must consider spectator safety. Negligence analysis depends on the circumstances and applicable law, not simply whether an injury occurred. A coach’s planning, supervision, equipment checks and response to known risks can matter. This is a curriculum overview, not advice about a specific legal dispute.", "The known risk and failure to take reasonable care are relevant to responsibility. Conversely, an injury in a properly managed activity does not automatically establish negligence. Distinguish governing-body discipline from civil or criminal legal processes."], "worked": "A coach knowingly uses damaged equipment despite a reported hazard.", "question": "Explain why an injury alone does not prove negligence, and identify two relevant aspects of a coach’s conduct.", "scheme": ["Sport can contain inherent risks even with reasonable care.", "Negligence requires context about duties and conduct, not injury alone.", "Appropriate supervision/planning is relevant.", "Responding to known equipment/environment hazards is relevant to reasonable care."], "checks": [{"q": "Which statement is accurate?", "opts": ["Sporting rules do not remove wider responsibilities concerning safety, contracts and care.", "A sports rulebook replaces every legal duty.", "Every injury proves a coach was negligent."], "a": 0, "why": "Sporting rules do not remove wider responsibilities concerning safety, contracts and care. The known risk and failure to take reasonable care are relevant to responsibility. Conversely, an injury in a properly managed activity does not automatically establish negligence. Distinguish governing-body discipline from civil or criminal legal processes."}], "animation": null}, {"id": "commercialisation", "unit": "contemporary", "title": "Commercialisation and stakeholder interests", "ref": "3.2.4.7", "summary": "Commercialisation can improve resources while distributing benefits and influence unevenly.", "notes": ["Sponsorship and media income can fund coaching, facilities and professional opportunities. They can also create pressure to prioritise marketable performers, reshape schedules, restrict access behind paywalls or privilege commercially attractive events. Evaluate effects on performer, coach, official, audience and sport separately. Sponsor influence, governing-body independence and audience access can create conflicts even when total revenue rises.", "Revenue is a benefit for provision, while changed access is a cost for part of the audience. A stronger analysis explains who benefits, who bears costs and under what conditions. Do not assume that commercial growth automatically improves grassroots access."], "worked": "A league gains new investment but moves fixtures to times difficult for families to attend.", "question": "Evaluate one benefit and one cost of a sport accepting an exclusive paid-streaming deal.", "scheme": ["Income may fund performers, events or facilities.", "Reliable funding can improve sporting provision.", "A paywall can reduce access for lower-income audiences.", "Reduced visibility/access may affect participation or fan relationships, so distribution matters as well as revenue."], "checks": [{"q": "Which statement is accurate?", "opts": ["All sponsorship revenue automatically reaches every grassroots club.", "Commercial growth has identical effects for all stakeholders.", "Commercialisation can improve resources while distributing benefits and influence unevenly."], "a": 2, "why": "Commercialisation can improve resources while distributing benefits and influence unevenly. Revenue is a benefit for provision, while changed access is a cost for part of the audience. A stronger analysis explains who benefits, who bears costs and under what conditions. Do not assume that commercial growth automatically improves grassroots access."}], "animation": null}, {"id": "sports-technology", "unit": "contemporary", "title": "Analytics, technology and data integrity", "ref": "3.2.4.8", "summary": "Useful sports analytics require valid measurements, consistent methods and interpretation in context.", "notes": ["Video supports technical and tactical analysis; GPS and motion tracking estimate movement demands; metabolic carts measure respiratory gases for indirect calorimetry. Data can inform fitness, skill, injury-risk monitoring, game analysis and talent identification. Calibration, sampling, accurate labelling, secure handling and transparent processing preserve integrity. Objective numbers can still be invalid or misleading if the instrument or comparison is unsuitable.", "An apparent training change may be a device effect. Standardise collection and interpret uncertainty. Equipment materials, adapted designs and facilities can improve inclusion or performance but introduce cost/fairness questions. An Olympic facility’s legacy should be assessed through sustained use and access, not its original construction alone."], "worked": "Two GPS devices report different distances from the same session because their sampling and processing differ.", "question": "A coach compares players’ GPS distance across different devices. Explain two reasons for caution and one improvement.", "scheme": ["Different sampling/processing can produce systematic differences.", "Distance alone does not capture intensity, role or tactical demands.", "Use standardised suitable devices/protocols and document changes.", "Interpret results with context, uncertainty and other relevant measures rather than ranking talent by one number."], "checks": [{"q": "Which statement is accurate?", "opts": ["Correlation in tracking data proves a particular load causes every injury.", "Useful sports analytics require valid measurements, consistent methods and interpretation in context.", "A numerical measurement is always valid regardless of equipment."], "a": 1, "why": "Useful sports analytics require valid measurements, consistent methods and interpretation in context. An apparent training change may be a device effect. Standardise collection and interpret uncertainty. Equipment materials, adapted designs and facilities can improve inclusion or performance but introduce cost/fairness questions. An Olympic facility’s legacy should be assessed through sustained use and access, not its original construction alone."}], "animation": null}, {"id": "nea-overview", "unit": "nea", "title": "Understanding the practical assessment", "ref": "4.5", "summary": "The NEA assesses practical performance and analysis; a revision website cannot certify a practical performance mark.", "notes": ["The AQA A-level NEA contributes 30% and is marked out of 90. It includes performance as a player/performer or coach in one approved activity, plus performance analysis. Assessment takes place in the full context of the activity, using the board’s activity-specific criteria and centre arrangements. Check the current approved list and evidence requirements with the teacher before planning.", "Drills can help learning but do not alone replace evidence against the required assessment conditions. This course provides preparation and reflection; its quizzes and AI feedback are practice only. Teachers must apply official criteria and authentication requirements to actual assessed work."], "worked": "A learner practises isolated drills but has not demonstrated decisions in the full activity context.", "question": "Explain why a high theory-quiz score cannot substitute for the practical component.", "scheme": ["Theory questions do not directly demonstrate sporting performance/coaching.", "The NEA uses approved activities and activity-specific criteria.", "Evidence must show the required full-context skills/decisions.", "Official assessment and moderation remain with the centre/board, not a website quiz."], "checks": [{"q": "Which statement is accurate?", "opts": ["The NEA assesses practical performance and analysis; a revision website cannot certify a practical performance mark.", "An AI score certifies the practical NEA mark.", "Any unlisted activity can be selected without checking AQA’s approved list."], "a": 0, "why": "The NEA assesses practical performance and analysis; a revision website cannot certify a practical performance mark. Drills can help learning but do not alone replace evidence against the required assessment conditions. This course provides preparation and reflection; its quizzes and AI feedback are practice only. Teachers must apply official criteria and authentication requirements to actual assessed work."}], "animation": null}, {"id": "performance-analysis", "unit": "nea", "title": "Analysing a performance with evidence", "ref": "4.5", "summary": "A strong performance analysis links specific evidence to relevant theory and its performance consequence.", "notes": ["Describe a precise action or decision in context, support it with observations or suitable data and identify the consequence. Apply relevant anatomy, biomechanics, skill or psychology to explain why the outcome occurred. Distinguish an observation from an inferred cause, and consider alternative explanations. Use appropriate permission and school procedures for any footage; this site does not require uploading athlete video.", "Video could identify foot position and centre-of-mass movement; fatigue or pressure might also matter. “Poor technique” is too vague. Identify the phase, evidence, mechanism and consequence, then decide what further evidence would discriminate between explanations."], "worked": "A fictional basketball player repeatedly loses balance after landing while closely contested.", "question": "Explain how to improve the claim “the player lost because they were not confident” using performance evidence.", "scheme": ["Identify specific actions, decisions or outcomes in defined situations.", "Gather relevant observations/data rather than inferring confidence from the result alone.", "Apply an appropriate theory and explain the proposed mechanism.", "Consider technical/tactical or situational alternatives and acknowledge what the evidence cannot establish."], "checks": [{"q": "Which statement is accurate?", "opts": ["A losing result proves low confidence caused the performance.", "Repeating a theory’s name replaces application to evidence.", "A strong performance analysis links specific evidence to relevant theory and its performance consequence."], "a": 2, "why": "A strong performance analysis links specific evidence to relevant theory and its performance consequence. Video could identify foot position and centre-of-mass movement; fatigue or pressure might also matter. “Poor technique” is too vague. Identify the phase, evidence, mechanism and consequence, then decide what further evidence would discriminate between explanations."}], "animation": null}, {"id": "improvement-plan", "unit": "nea", "title": "Planning and evaluating an improvement", "ref": "4.5", "summary": "An improvement plan should target an evidenced weakness and define how progress will be judged.", "notes": ["Set a baseline, choose a specific weakness and justify a suitable intervention with theory. Define a realistic progression, feedback and review method. Use comparable conditions to evaluate change and distinguish improvement in a practice drill from transfer to competition. Keep assessed work the learner’s own and follow centre rules about assistance; this workshop supports revision and planning, not the generation of an assessed submission.", "The intervention may not have transferred to the competitive context. Include representative practice and a later full-context review. A plan should explain why the chosen method addresses the mechanism, rather than list exercises unrelated to the observed weakness."], "worked": "A fictional performer improves a drill score but still makes the same error under match pressure.", "question": "Design the evaluation approach for a fictional plan intended to improve decision making under defensive pressure.", "scheme": ["Record a baseline using representative pressured situations.", "Define a specific outcome such as appropriate passing decisions, with consistent criteria.", "Repeat comparable observation after the intervention, including full-context transfer.", "Consider opponent difficulty, fatigue and sample size before attributing every change to the plan."], "checks": [{"q": "Which statement is accurate?", "opts": ["A plan needs no baseline if the performer feels more confident.", "An improvement plan should target an evidenced weakness and define how progress will be judged.", "A better drill score guarantees improved competitive decisions."], "a": 1, "why": "An improvement plan should target an evidenced weakness and define how progress will be judged. The intervention may not have transferred to the competitive context. Include representative practice and a later full-context review. A plan should explain why the chosen method addresses the mechanism, rather than list exercises unrelated to the observed weakness."}], "animation": null}], "sources": [{"title": "AQA 7582 specification and assessment", "url": "https://www.aqa.org.uk/subjects/physical-education/a-level/physical-education-7582/specification/specification-at-a-glance"}, {"title": "Paper 1 subject content", "url": "https://www.aqa.org.uk/subjects/physical-education/a-level/physical-education-7582/specification/subject-content/factors-affecting-participation-in-physical-activity-and-sport"}, {"title": "Paper 2 subject content", "url": "https://www.aqa.org.uk/subjects/physical-education/a-level/physical-education-7582/specification/subject-content/factors-affecting-optimal-performance-in-physical-activity-and-sport"}, {"title": "Official assessment and NEA guidance", "url": "https://www.aqa.org.uk/subjects/physical-education/a-level/physical-education-7582/specification/scheme-of-assessment"}]};
window.PE_PAPERS=[{"id": "pe-paper-1", "paper": 1, "title": "Paper 1 · Participation and performance foundations", "marks": 105, "minutes": 120, "coverage": ["Applied anatomy and physiology", "Skill acquisition", "Sport and society"], "questions": [{"title": "Section A · Applied anatomy and physiology", "stem": "<p><b>Fictional case:<\/b> A rower completes a steady exercise test. At one stage heart rate is 150 beats min⁻¹, stroke volume 140 mL beat⁻¹, breathing frequency 32 min⁻¹ and tidal volume 2.5 L. Later the rower completes a maximal finishing effort.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["Myoglobin is the main protein transporting oxygen around the blood.", "A rightward shift of the oxyhaemoglobin curve promotes oxygen unloading at a given partial pressure.", "A Bohr shift makes haemoglobin bind oxygen more tightly at active tissues."], "a": 1, "m": 1, "ms": ["A rightward shift of the oxyhaemoglobin curve promotes oxygen unloading at a given partial pressure. Lower affinity means more oxygen can be released to the active tissue. The curve is not a direct graph of how much oxygen the athlete consumes. Describe the axes, the direction of the shift and its effect at a specified partial pressure."]}, {"q": "Which statement is accurate?", "opts": ["Type IIx fibres are the most fatigue-resistant fibres.", "Every endurance movement uses only type I fibres.", "Type I, IIa and IIx fibres differ in force, fatigue resistance and metabolic characteristics."], "a": 2, "m": 1, "ms": ["Type I, IIa and IIx fibres differ in force, fatigue resistance and metabolic characteristics. Type I characteristics suit sustained aerobic demand; fast fibres support high force and power. Do not claim that a marathon uses no fast fibres or a jump uses no aerobic metabolism. Recruitment changes with force requirements and fatigue."]}, {"q": "Which statement is accurate?", "opts": ["Spatial summation means increasing the size of one action potential.", "Force can increase by recruiting more motor units and by increasing firing frequency.", "All-or-none means the whole muscle can produce only one force."], "a": 1, "m": 1, "ms": ["Force can increase by recruiting more motor units and by increasing firing frequency. Extra force does not mean each fibre produces half an action potential. More units and altered firing frequency grade whole-muscle force. Muscle spindles detect stretch; Golgi tendon organs monitor tension. These proprioceptors provide feedback relevant to movement and flexibility training. In the syllabus model of PNF, a controlled isometric contraction and subsequent relaxation are linked with reduced resistance to a further stretch, including inhibitory effects associated with tension feedback. A muscle spindle responds to length/change in length; the Golgi tendon organ responds to tension. PNF needs suitable supervision rather than forcing a painful stretch."]}, {"q": "Calculate minute ventilation, giving the correct unit.", "m": 2, "ms": ["32 × 2.5.", "80 L min⁻¹."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice.", "answer": 80}, {"q": "Calculate cardiac output in L min⁻¹, showing your working.", "m": 3, "ms": ["150 × 140 = 21 000 mL min⁻¹.", "Divide by 1000 to convert mL to L.", "21 L min⁻¹."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice.", "answer": 21}, {"q": "Explain how blood redistribution and oxygen extraction support the working muscles.", "m": 4, "ms": ["Working muscle arterioles dilate, increasing local flow.", "Some less active beds can constrict, redistributing available flow.", "Muscle extraction increases arterio-venous oxygen difference.", "Greater flow and extraction support increased oxygen consumption/aerobic ATP resynthesis."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse how the rower’s cardiovascular and respiratory responses work together to support sustained exercise.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Heart rate/stroke volume and cardiac output.", "Ventilation, alveolar gradients, haemoglobin carriage and muscle unloading.", "Venous return and extraction; links between mechanisms rather than unrelated lists.", "Training status/intensity and limits of interpreting a single test stage."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate the claim that successful rowing performance depends only on aerobic energy supply. Use the case and draw on anatomy, energy systems and neuromuscular function.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Aerobic capacity is important for sustained work, with delivery and extraction adaptations.", "ATP–PC and glycolytic supply contribute during starts, changes of pace and the finishing effort.", "All systems overlap; contribution depends on intensity/duration rather than an abrupt on/off switch.", "Fibre recruitment, force, technique and recovery also affect performance.", "A judgement should explain why aerobic importance does not imply sole dependence."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}, {"title": "Section B · Skill acquisition", "stem": "<p><b>Fictional case:<\/b> A novice basketball player can pass accurately in an unopposed drill but struggles when defenders and several passing options are introduced. Recorded reaction time is 0.28 s and movement time 0.34 s.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["An open skill occurs only outdoors.", "Skill classification depends on the specific action and environment rather than the sport’s name alone.", "Every skill within a sport occupies exactly the same continuum position."], "a": 1, "m": 1, "ms": ["Skill classification depends on the specific action and environment rather than the sport’s name alone. The free throw is relatively closed and self-paced; the contested pass is more open and externally paced. Both have large muscle involvement but also fine control. Continua permit intermediate positions: do not force every action into a universal binary label."]}, {"q": "Which statement is accurate?", "opts": ["Knowledge of performance is just the final score.", "Manual guidance should be used continuously with every expert.", "Knowledge of results describes the outcome; knowledge of performance describes how the movement was executed."], "a": 2, "m": 1, "ms": ["Knowledge of results describes the outcome; knowledge of performance describes how the movement was executed. Distance is knowledge of results; release-angle feedback is knowledge of performance. Corrective feedback can be constructive rather than simply discouraging. Plan opportunities for the learner to judge the movement before receiving external information."]}, {"q": "Which statement is accurate?", "opts": ["Transfer can help, hinder or have little effect on learning another skill.", "Transfer is always positive.", "Bilateral transfer means moving from one sport to another."], "a": 0, "m": 1, "ms": ["Transfer can help, hinder or have little effect on learning another skill. An established response can interfere with the new technique, illustrating negative transfer. A coach can highlight the differences and provide focused practice. Improvement after practice alone does not prove positive transfer without comparing appropriate starting conditions."]}, {"q": "Calculate response time and distinguish it from reaction time.", "m": 2, "ms": ["Response time = 0.28 + 0.34 = 0.62 s.", "Reaction time ends at movement initiation; response time also includes movement."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain why adding realistic passing alternatives can increase reaction time.", "m": 3, "ms": ["The player must discriminate/select among more possible responses.", "Hick’s law predicts longer choice reaction time as alternatives increase.", "A novice may need more processing before selecting the pass; anticipation/learning can modify the effect."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Justify distributed and variable practice for this player.", "m": 4, "ms": ["Distributed practice includes rest/feedback and helps manage novice fatigue/attention.", "Explain how this preserves practice quality.", "Variable practice changes relevant defender/target conditions.", "It develops adaptable responses suited to the open competitive skill."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse how guidance and feedback could change as this player progresses towards autonomous performance.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Clear demonstration and manageable cues for cognitive learning.", "Specific knowledge of performance as technique becomes more consistent.", "Intrinsic feedback and selective external feedback at greater expertise.", "Avoid dependence/overload; feedback should respond to evidence rather than a fixed schedule."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate whether repeating the same unopposed passing drill is sufficient preparation for competitive basketball. Apply skill classification, information processing and schema theory.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Repetition can establish basic coordination and confidence.", "Competition is open and requires selective attention, perception and response selection.", "Variable conditions support adaptable recall/recognition schemas.", "Representative pressure and feedback support transfer, while excessive complexity can overload a novice.", "A staged whole/part or progressive practice approach should be justified with the learner’s needs."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}, {"title": "Section C · Sport and society", "stem": "<p><b>Fictional case:<\/b> A local football project offers discounted sessions but has no accessible transport and little provision at times suitable for carers. A sponsor offers funding in exchange for prominent coverage of the elite team rather than the community sessions.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["Pre-industrial mob football used one nationally administered rulebook.", "Real tennis and mob football were equally accessible to all social classes.", "Pre-industrial sporting recreation reflected local conditions and a strongly divided society."], "a": 2, "m": 1, "ms": ["Pre-industrial sporting recreation reflected local conditions and a strongly divided society. Local rules and irregular festival opportunities fit popular recreation. Limited communication made uniform rules harder to spread. Compare this with elite access to real tennis rather than claiming every person in the period played the same games."]}, {"q": "Which statement is accurate?", "opts": ["Amateur and professional status reflected social values and access to money as well as payment rules.", "Amateur status has always guaranteed equal class access.", "Women’s sporting opportunities changed identically in every sport."], "a": 0, "m": 1, "ms": ["Amateur and professional status reflected social values and access to money as well as payment rules. A formally equal amateur rule can have unequal class effects. Increased female visibility and investment can support opportunity, yet coverage, facilities and leadership access can remain uneven. Distinguish the historical pattern from the position of every current participant."]}, {"q": "Which statement is accurate?", "opts": ["Unequal participation proves fixed differences in ability.", "Participation is shaped by interacting social opportunities, expectations and personal choices.", "Prejudice and discrimination always mean exactly the same action."], "a": 1, "m": 1, "ms": ["Participation is shaped by interacting social opportunities, expectations and personal choices. The stereotype can shape expectations and discriminatory provision, which may reduce participation. Do not infer innate lack of interest from unequal participation. Disability, ethnicity, gender and disadvantage may intersect rather than operating independently."]}, {"q": "Distinguish prejudice from discrimination.", "m": 2, "ms": ["Prejudice is a pre-judged attitude or belief.", "Discrimination is unequal treatment/action; an applied example may show the distinction."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain how improved transport helped the development of organised sport during industrialisation.", "m": 3, "ms": ["Travel between towns became more practical.", "Regular inter-club fixtures became possible.", "Wider competition encouraged common rules and governing structures."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain two reasons why discounted sessions alone may not remove participation barriers in the case.", "m": 4, "ms": ["Transport/accessibility remains a barrier.", "A reduced fee does not make an inaccessible journey possible.", "Timing/caring responsibilities remain a barrier.", "A session can be affordable yet impractical to attend regularly."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse the interrelationship between media, sponsorship and sport using the proposed funding agreement.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Coverage attracts audience and commercial interest.", "Funding can improve provision and support elite opportunities.", "Sponsor/media preferences may direct resources towards marketable events.", "Consider effects on grassroots access and stakeholder priorities, rather than treating revenue as an automatic universal benefit."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate how social institutions and commercial change have shaped access to football from industrialisation to the present. Connect historical development with the fictional project.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Factories, churches, schools, authorities and transport contributed to organised provision.", "Codification and governing bodies supported regular competition.", "Class, gender, disability and economic inequalities affect opportunity.", "Post-war media/commercialisation expanded resources and visibility but distributed them unevenly.", "A developed judgement should identify matched participation solutions and avoid portraying access as automatically equal today."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}]}, {"id": "pe-paper-2", "paper": 2, "title": "Paper 2 · Optimising sporting performance", "marks": 105, "minutes": 120, "coverage": ["Exercise physiology and biomechanics", "Sport psychology", "Sport, society and technology"], "questions": [{"title": "Section A · Exercise physiology and biomechanics", "stem": "<p><b>Fictional case:<\/b> An 80 kg sprinter experiences a triangular horizontal resultant-force pulse of peak 1200 N lasting 0.20 s. Their coach plans a training block and taper. All values are simplified educational data.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["Lever arms are measured from the end of the limb regardless of the force line.", "Mechanical advantage equals effort arm divided by resistance arm.", "A third-class lever always multiplies force above the effort."], "a": 1, "m": 1, "ms": ["Mechanical advantage equals effort arm divided by resistance arm. Resistance moment is 30 N m, so balancing effort is 600 N. Mechanical advantage is 0.05/0.30 = 1/6: force disadvantage. The limb can still be effective because speed and range at the load may be valuable. The model simplifies distributed segment mass and changing muscle moment arms."]}, {"q": "Which statement is accurate?", "opts": ["Moment of inertia depends only on total mass and never its distribution.", "With negligible external torque, reducing moment of inertia increases angular velocity.", "Tucking creates new angular momentum without external torque."], "a": 1, "m": 1, "ms": ["With negligible external torque, reducing moment of inertia increases angular velocity. Tucking reduces moment of inertia and increases angular velocity; opening increases inertia and slows rotation. Angular momentum is not created by tucking. External torque during take-off establishes the initial rotation, so take-off and flight must be analysed separately."]}, {"q": "Which statement is accurate?", "opts": ["Release speed, angle and height influence projectile range; air resistance can change the flight path.", "Every sporting projectile must have a 45° optimal release angle.", "Gravity acts only after a projectile reaches its highest point."], "a": 0, "m": 1, "ms": ["Release speed, angle and height influence projectile range; air resistance can change the flight path. Their ideal equal-height ranges match because sin(2θ) is equal, but flight times and peak heights differ. Real performers may release at different speeds as angle changes. Label model assumptions and avoid applying 45° as a universal coaching rule."]}, {"q": "Calculate the impulse from the horizontal force pulse.", "m": 2, "ms": ["½ × 1200 × 0.20.", "120 N s."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice.", "answer": 120}, {"q": "Calculate the resulting change in horizontal velocity, showing the relationship used.", "m": 3, "ms": ["Impulse = change in momentum = mass × velocity change.", "Velocity change = 120/80.", "1.5 m s⁻¹ in the force direction."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice.", "answer": 1.5}, {"q": "Explain how specificity and recovery should influence the sprinter’s training design.", "m": 4, "ms": ["Include appropriate high-intensity actions matched to sprint force/speed demands.", "Explain how these target the required adaptations.", "Provide suitable recovery between quality efforts and sessions.", "Recovery supports restored capacity/adaptation and limits loss of quality from accumulated fatigue."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse why the sprinter’s coach should use more than peak force when interpreting the test and planning training.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Impulse depends on force–time area, including duration and shape.", "Mass influences the velocity change produced by a given impulse.", "Direction and whether force is resultant matter.", "Standardisation, repeated tests and relevance to competitive technique support interpretation."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate a plan that increases training intensity and volume every day until a championship. Apply training principles, periodisation, recovery and biomechanics.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Progressive overload requires managed demand, not unlimited daily increases.", "Specificity and high-quality force application matter for sprinting.", "Fatigue can alter coordination and reduce effective impulse or movement quality.", "Recovery, sleep and suitable nutrition support adaptation; injury risks require management.", "A taper can reduce volume while retaining suitable intensity; timing should respond to evidence and individual needs."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}, {"title": "Section B · Sport psychology", "stem": "<p><b>Fictional case:<\/b> An experienced penalty taker becomes worried before a final, reports tense shoulders and misses. Their coach concludes that the miss proves a weak personality. Several teammates also argue and stop supporting one another.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["Every performer’s optimum arousal is exactly the same.", "Drive theory predicts that every error disappears at high arousal.", "Arousal theories make different predictions, and the most useful level depends on performer and task."], "a": 2, "m": 1, "ms": ["Arousal theories make different predictions, and the most useful level depends on performer and task. The inverted-U offers a simple prediction but does not fix the same optimum for everyone. A catastrophe curve is a theoretical relationship, not a diagnostic graph of a particular student. Consider skill complexity, expertise and anxiety when making a recommendation."]}, {"q": "Which statement is accurate?", "opts": ["Trait anxiety refers only to one moment before a match.", "Cognitive anxiety concerns worry; somatic anxiety concerns bodily responses.", "High heart rate proves cognitive anxiety in every situation."], "a": 1, "m": 1, "ms": ["Cognitive anxiety concerns worry; somatic anxiety concerns bodily responses. Pulse alone cannot establish that the player is anxious. Combine measures and context, using consistent timing. A change within a person may be more informative than comparing raw scores between people with different baselines."]}, {"q": "Which statement is accurate?", "opts": ["SMARTER goals never need revision.", "Process and performance goals give performers targets they can control more directly than final results.", "An outcome goal is always fully under the athlete’s control."], "a": 1, "m": 1, "ms": ["Process and performance goals give performers targets they can control more directly than final results. Winning is an outcome goal; a personal time is a performance goal; pacing behaviours are process goals. They can work together. Make the target appropriate to baseline and available time, then evaluate progress rather than merely adding the word SMARTER to a plan."]}, {"q": "Distinguish cognitive and somatic anxiety using the case.", "m": 2, "ms": ["Worry about the final/missing is cognitive anxiety.", "Bodily tension such as tense shoulders is somatic anxiety."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain an interactionist challenge to the coach’s personality conclusion.", "m": 3, "ms": ["Behaviour reflects personal and environmental factors.", "The final adds pressure/evaluation and may change the athlete’s state.", "One missed penalty does not establish a fixed weak trait or prove its cause."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Justify one cognitive and one somatic stress-management technique for the athlete.", "m": 4, "ms": ["Use a practised task cue, imagery or credible positive self-talk.", "Explain how it redirects worry towards controllable execution.", "Use practised breathing, centering or relaxation.", "Explain the link to bodily tension and the need to practise/evaluate the routine."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse how feedback and attribution after the miss could affect the athlete’s motivation and self-efficacy.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Stable uncontrollable inability explanations can reduce expectations/persistence.", "Evidence-based controllable technique/preparation explanations can support change.", "Mastery progress, credible persuasion and relevant modelling can support efficacy.", "Avoid false reassurance or blaming every failure on the athlete; consider alternative causes."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate how leadership, cohesion and arousal management could help the whole team prepare for another final.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Distinguish task/social cohesion and coordination/motivational losses.", "Use roles, shared goals and representative practice to target actual group processes.", "Leadership should fit required/preferred behaviour and the sporting situation.", "Arousal theory supports individualised preparation rather than one universal optimum.", "Connect individual confidence and group functioning, considering limitations and measures of improvement."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}, {"title": "Section C · Sport, society and technology", "stem": "<p><b>Fictional case:<\/b> A club buys a tracking system. A supplier claims the data prove which players will become elite. Devices differ between age groups. Sponsorship pays for the system but the junior programme loses funding. A player is pressured to use a prohibited substance to keep a contract.<\/p>", "parts": [{"q": "Which statement is accurate?", "opts": ["Legal compliance and ethical sporting behaviour are related but not identical.", "Every action not penalised by an official is automatically sportsmanlike.", "Positive deviance means that a harmful behaviour is medically beneficial."], "a": 0, "m": 1, "ms": ["Legal compliance and ethical sporting behaviour are related but not identical. The behaviour may illustrate gamesmanship even if no formal penalty is given. Explain the intent, rule context and effect on fair competition. Playing through injury may be praised as commitment while causing harm, illustrating why overconformity needs critical evaluation."]}, {"q": "Which statement is accurate?", "opts": ["Every prohibited substance has exactly the same sporting effect.", "Doping can offer a perceived performance advantage while creating health, fairness and welfare harms.", "EPO improves oxygen carriage without any potential health risk."], "a": 1, "m": 1, "ms": ["Doping can offer a perceived performance advantage while creating health, fairness and welfare harms. Perceived unfair competition can encourage a coercive cycle, but does not remove ethical responsibility. Sanctions, welfare harms and loss of trust affect both performer and sport. A balanced debate should address fairness and autonomy without treating drug use as a safe training strategy; testing procedures themselves are outside this specification’s examined detail."]}, {"q": "Which statement is accurate?", "opts": ["All physical activity must aim at elite competition.", "Physical education is defined only by winning matches.", "Physical education, recreation and competitive sport have overlapping but different purposes."], "a": 2, "m": 1, "ms": ["Physical education, recreation and competitive sport have overlapping but different purposes. The lesson illustrates educational aims; the competition illustrates school sport. A recreational participant may value enjoyment over rankings. Classifications can overlap, so justify the dominant purpose rather than relying on the venue alone."]}, {"q": "Distinguish validity and reliability in evaluating the tracking measurements.", "m": 2, "ms": ["Validity concerns whether the measure assesses the intended quality.", "Reliability concerns consistency under comparable conditions."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain one role of each: a national governing body, UK Sport and an institute of sport.", "m": 3, "ms": ["A governing body provides sport-specific organisation/pathways.", "UK Sport supports the high-performance Olympic/Paralympic system.", "An institute provides specialist services such as sports science, medicine or performance support."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Explain two problems with comparing the age groups’ tracking data directly.", "m": 4, "ms": ["Different device sampling/processing can cause systematic measurement differences.", "This can mimic a performance difference.", "Age/maturation, role or session demands can differ.", "Distance/tracking alone cannot isolate talent or predict every future elite performer."], "note": "Indicative content: credit equivalent accurate reasoning. Do not award the same idea twice."}, {"q": "Analyse how data integrity and contextual interpretation could improve the club’s use of sports analytics.", "m": 8, "lor": [["7–8", "Accurate, developed explanation and analysis, applied closely to the context, with a supported judgement."], ["5–6", "Mostly accurate knowledge and some developed application/analysis; the conclusion has support but may be uneven."], ["3–4", "Some relevant knowledge and application; development or analysis is limited."], ["1–2", "Isolated relevant statements with little development or application."], ["0", "No creditworthy response."]], "ind": ["Standardise/calibrate suitable equipment and document processing.", "Use accurate labelling, consistent conditions and appropriate access/security.", "Consider uncertainty, missing data and multiple measures.", "Interpret with role, maturation and opportunity; correlation/prediction is not proof of a single cause."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}, {"q": "Evaluate whether commercial and technological development necessarily improves sport. Use the case, considering participation, elite performance, ethics and performer welfare.", "m": 15, "lor": [["12–15", "Accurate, well-selected knowledge with sustained contextual application, connected analysis and balanced evaluation leading to a well-supported judgement."], ["8–11", "Generally accurate knowledge with relevant application and developed analysis/evaluation, though uneven in places; a reasoned judgement."], ["4–7", "Some relevant knowledge and application; analysis/evaluation is partial or mostly asserted."], ["1–3", "Basic isolated relevant statements with little application or developed reasoning."], ["0", "No creditworthy response."]], "ind": ["Funding and technology can improve coaching, analysis, facilities and opportunity.", "Unequal allocation may reduce grassroots provision or inclusion.", "Overclaiming data can distort selection and reinforce unequal opportunities.", "Contract/reward pressures may interact with doping and welfare harms; banned enhancement is not justified by commercial gain.", "Balance stakeholders and conditions, concluding how governance and evidence can influence whether benefits are realised."], "ms": [], "note": "Original Prodigy best-fit levels, not AQA’s official marking grid. Assess the whole response, then choose a defensible mark within the band. Indicative content is not a point-per-mark checklist."}]}]}];
